local _grs_anim = {}
local _grs_new_insts = setmetatable({}, {__mode = "k"})
local _sim_clock = 0

local function _install_early_guard_compat()
    if type(utf8) == "table" then
        utf8.nfdnormalize = utf8.nfdnormalize or function(value) return value end
        utf8.nfcnormalize = utf8.nfcnormalize or function(value) return value end
        utf8.graphemes = utf8.graphemes or function(value)
            local index = 0
            local text = tostring(value or "")
            return function()
                index = index + 1
                if index <= #text then return index, index end
            end
        end
    end
    if type(math) == "table" then
        math.isnan = math.isnan or function(value) return value ~= value end
        math.isfinite = math.isfinite or function(value) return value == value and value ~= math.huge and value ~= -math.huge end
        math.isinf = math.isinf or function(value) return value == math.huge or value == -math.huge end
    end
    if type(debug) == "table" then
        debug.setmemorycategory = debug.setmemorycategory or function() end
        debug.profilebegin = debug.profilebegin or function() end
        debug.getmemorycategory = debug.getmemorycategory or function() return "" end
        debug.resetmemorycategory = debug.resetmemorycategory or function() end
        debug.profileend = debug.profileend or function() end
    end
    if type(task) == "table" then
        task.desynchronize = task.desynchronize or function() end
        task.synchronize = task.synchronize or function() end
    end
end
_install_early_guard_compat()

local _active_tweens = setmetatable({}, { __mode = "k" })

local function _advance_active_tweens()
    for tween, state in pairs(_active_tweens) do
        if state.playing and state.instance ~= nil then
            local duration = state.duration
            local alpha = duration > 0 and ((_sim_clock - state.started) / duration) or 1
            if alpha < 0 then alpha = 0 end
            if alpha > 1 then alpha = 1 end
            for key, goal in pairs(state.goals) do
                local start = state.starts[key]
                local value = goal
                if type(goal) == "number" then
                    local startNumber = tonumber(start) or 0
                    value = startNumber + (goal - startNumber) * alpha
                elseif alpha < 1 then
                    value = start
                end
                pcall(function() state.instance[key] = value end)
            end
            if alpha >= 1 then
                state.playing = false
                state.completed = true
                for _, callback in pairs(state.callbacks) do
                    if type(callback) == "function" then
                        pcall(callback, Enum and Enum.PlaybackState and Enum.PlaybackState.Completed)
                    end
                end
            end
        end
    end
end

-- Inheritance-aware instance metatable for Roblox API dispatch
local _full_cache   = {}
local _signal_cache = setmetatable({}, {__mode = "k"})

local function _get_full_members(cls)
    if _full_cache[cls] then return _full_cache[cls] end
    local all, cur, seen = {}, cls, {}
    while cur and cur ~= '' and not seen[cur] do
        seen[cur] = true
        local own = _ROBLOX_MEMBERS[cur]
        if own then for k,v in pairs(own) do if not all[k] then all[k]=v end end end
        cur = _ROBLOX_SUPER[cur] or ''
    end
    _full_cache[cls] = all
    return all
end

local _sig_mt = { __type = "RBXScriptSignal" }
local function _mk_signal()
    local cbs = {}
    local s = setmetatable({}, _sig_mt)
    s.Connect = function(_, fn)
        if type(fn)~='function' then
            return {Disconnect=function()end,disconnect=function()end,Connected=false}
        end
        local id = tostring(fn)..tostring(#cbs+1)
        cbs[id] = fn
        local conn = {Connected=true}
        conn.Disconnect = function() cbs[id]=nil; conn.Connected=false end
        conn.disconnect = conn.Disconnect
        return conn
    end
    s.connect = s.Connect
    s.Once = function(self2,fn)
        local c; c = s:Connect(function(...) c:Disconnect(); fn(...) end); return c
    end
    s.once = s.Once
    s.Wait = function() return nil end; s.wait = s.Wait
    s.Fire = function(_,...) for _,fn in pairs(cbs) do pcall(fn,...) end end
    return s
end

local function _get_sig(inst, k)
    local key = (type(inst) == "table" or type(inst) == "userdata") and inst or tostring(inst)
    if not _signal_cache[key] then _signal_cache[key] = {} end
    if not _signal_cache[key][k] then _signal_cache[key][k] = _mk_signal() end
    return _signal_cache[key][k]
end

local _BASE_EVT = {
    AncestryChanged=true,Changed=true,ChildAdded=true,ChildRemoved=true,
    DescendantAdded=true,DescendantRemoving=true,Destroying=true,
    AttributeChanged=true,
}

local _instance_children = setmetatable({}, { __mode = "k" })

local function _set_instance_parent(instance, parent)
    if rawget(instance, "__destroyed") then
        local name = rawget(instance, "Name") or rawget(instance, "ClassName") or "Instance"
        error(string.format("The Parent property of %s is locked, current parent: NULL, new parent %s", tostring(name), parent == nil and "NULL" or tostring(parent)), 2)
    end
    if parent ~= nil then
        if type(parent) ~= "table" or rawget(parent, "ClassName") == nil then
            error("Unable to assign property Parent. Object expected, got " .. typeof(parent), 2)
        end
        if rawget(parent, "__destroyed") then
            error("The Parent property of " .. tostring(rawget(instance, "Name") or "Instance") .. " is locked", 2)
        end
        local cur = parent
        local depth = 0
        while type(cur) == "table" and depth < 128 do
            if cur == instance then
                error("Attempt to set parent would result in circular reference", 2)
            end
            cur = rawget(cur, "Parent")
            depth = depth + 1
        end
    end
    local old_parent = rawget(instance, "Parent")
    if old_parent == parent then return end
    local old_children = old_parent ~= nil and _instance_children[old_parent]
    if old_children then
        for i = #old_children, 1, -1 do
            if old_children[i] == instance then
                table.remove(old_children, i)
            end
        end
    end
    rawset(instance, "Parent", parent)
    if parent == nil then return end
    local children = _instance_children[parent]
    if not children then
        children = {}
        _instance_children[parent] = children
    end
    for _, child in ipairs(children) do
        if child == instance then return end
    end
    children[#children + 1] = instance
end

local function _instance_descendant(instance, ancestor)
    local seen = {}
    local current = instance
    while current ~= nil and not seen[current] do
        if current == ancestor then return true end
        seen[current] = true
        current = rawget(current, "Parent")
    end
    return false
end


