local _build_instance
local _fake_instance_mt = {}
_fake_instance_mt.__metatable = "Instance"
_fake_instance_mt.__tostring  = function(s) return rawget(s, "ClassName") or "Instance" end
_fake_instance_mt.__newindex  = function(s, k, v)
    if k == "Parent" then
        _set_instance_parent(s, v)
    elseif k == "MaxItems" and rawget(s, "ClassName") == "Debris" then
        local n = tonumber(v)
        if n == nil then
            error("Unable to assign property MaxItems. number expected", 2)
        end
        rawset(s, "__debris_max_items", n >= 0 and math.floor(n) or math.ceil(n))
    else
        rawset(s, k, v)
    end
end
_fake_instance_mt.__index     = function(self, k)
    if k == "MaxItems" and rawget(self, "ClassName") == "Debris" then
        local v = rawget(self, "__debris_max_items")
        return v ~= nil and v or 1000
    end
    if k=='GetJoints' then
        return function(s2)
            local ws = rawget(_G, "workspace") or (game and game.Workspace)
            local function is_in_ws(inst)
                local node = inst
                local d = 0
                while type(node) == "table" and d < 128 do
                    if node == ws then return true end
                    node = rawget(node, "Parent")
                    d = d + 1
                end
                return false
            end
            if not ws or not is_in_ws(s2) then return {} end
            local out = {}
            local function walk(node)
                for _, ch in ipairs(_instance_children[node] or {}) do
                    local cn = rawget(ch, "ClassName") or ""
                    if (cn == "Weld" or cn == "WeldConstraint" or cn == "Motor6D" or cn == "ManualWeld" or cn == "Snap" or cn == "Glue" or cn == "Motor")
                        and rawget(ch, "Enabled") ~= false
                        and (rawget(ch, "Part0") == s2 or rawget(ch, "Part1") == s2) then
                        local p0, p1 = rawget(ch, "Part0"), rawget(ch, "Part1")
                        if p0 and p1 and is_in_ws(p0) and is_in_ws(p1) then
                            out[#out + 1] = ch
                        end
                    end
                    walk(ch)
                end
            end
            walk(ws)
            return out
        end
    end
    if k=='IsA' then
        return function(s2, cls)
            local cur,seen = rawget(s2,'ClassName') or '', {}
            while cur and cur~='' and not seen[cur] do
                if cur==cls then return true end
                seen[cur]=true; cur=_ROBLOX_SUPER[cur] or ''
            end
            return false
        end
    end
    if k=='FindFirstChild' or k=='FindFirstChildOfClass' or k=='FindFirstChildWhichIsA' then
        return function(s2, name, recursive)
            local children = _instance_children[s2] or {}
            for _, child in ipairs(children) do
                local class_name = rawget(child, "ClassName") or ""
                local child_name = rawget(child, "Name") or class_name
                if (k == "FindFirstChild" and child_name == name)
                    or (k == "FindFirstChildOfClass" and class_name == name)
                    or (k == "FindFirstChildWhichIsA" and type(child.IsA) == "function" and child:IsA(name)) then
                    return child
                end
                if recursive and type(child[k]) == "function" then
                    local found = child[k](child, name, true)
                    if found then return found end
                end
            end
            return nil
        end
    end
    if k=='FindFirstAncestor' or k=='FindFirstAncestorOfClass' or k=='FindFirstAncestorWhichIsA' then
        return function(s2, name)
            local parent = rawget(s2, "Parent")
            while type(parent) == "table" do
                local class_name = rawget(parent, "ClassName") or ""
                local parent_name = rawget(parent, "Name") or class_name
                if (k == "FindFirstAncestor" and parent_name == name)
                    or (k == "FindFirstAncestorOfClass" and class_name == name)
                    or (k == "FindFirstAncestorWhichIsA" and type(parent.IsA) == "function" and parent:IsA(name)) then
                    return parent
                end
                parent = rawget(parent, "Parent")
            end
            return nil
        end
    end
    if k=='GetChildren' then
        return function(s2)
            local result = {}
            for _, child in ipairs(_instance_children[s2] or {}) do result[#result + 1] = child end
            return result
        end
    end
    if k=='GetDescendants' then
        return function(s2)
            local result = {}
            local function walk(node)
                for _, child in ipairs(_instance_children[node] or {}) do
                    result[#result + 1] = child
                    walk(child)
                end
            end
            walk(s2)
            return result
        end
    end
    if k=='GetTags' then return function() return {} end end
    if k=='WaitForChild' then
        return function(s2, name)
            return s2:FindFirstChild(name)
        end
    end
    if k=='Clone' then
        return function(s2, parent)
            local function cloneNode(source, cloneParent)
                if rawget(source, "__destroyed") or rawget(source, "Archivable") == false then
                    return nil
                end
                local clone = _build_instance(rawget(source, "ClassName") or "Instance", nil)
                rawset(clone, "Name", rawget(source, "Name") or rawget(source, "ClassName") or "Instance")
                for key, value in pairs(source) do
                    if key ~= "Parent" and key ~= "ClassName" and key ~= "Name" and key ~= "__attributes" and key ~= "__destroyed"
                       and type(value) ~= "function" then
                        rawset(clone, key, value)
                    end
                end
                local sourceAttrs = rawget(source, "__attributes")
                if type(sourceAttrs) == "table" then
                    local attrs = {}
                    for name, value in pairs(sourceAttrs) do attrs[name] = value end
                    rawset(clone, "__attributes", attrs)
                end
                for _, child in ipairs(_instance_children[source] or {}) do
                    cloneNode(child, clone)
                end
                if cloneParent ~= nil then
                    _set_instance_parent(clone, cloneParent)
                end
                return clone
            end
            return cloneNode(s2, parent)
        end
    end
    if k=='Destroy' or k=='Remove' or k=='ClearAllChildren' or k=='Disconnect' then
        return function(s2)
            if k == "ClearAllChildren" then
                for _, child in ipairs(_instance_children[s2] or {}) do _set_instance_parent(child, nil) end
                _instance_children[s2] = {}
            elseif k == "Destroy" or k == "Remove" then
                for _, child in ipairs(_instance_children[s2] or {}) do child:Destroy() end
                _instance_children[s2] = nil
                _set_instance_parent(s2, nil)
                rawset(s2, "__destroyed", true)
            end
        end
    end
    if k=='GetPropertyChangedSignal' then
        return function(s2,p) return _get_sig(s2,'__pcs:'..p) end end
    if k=='GetAttributeChangedSignal' then
        return function(s2,p) return _get_sig(s2,'__acs:'..p) end end
        if k=='GetFullName' then
        return function(s2)
            local names = {}
            local node = s2
            local depth = 0
            while node ~= nil and depth < 128 do
                local nodeType = type(node)
                if nodeType ~= "table" and nodeType ~= "userdata" then break end
                depth = depth + 1
                local okName, name = pcall(function() return node.Name end)
                local okClass, className = pcall(function() return node.ClassName end)
                names[#names + 1] = (okName and name) or (okClass and className) or "Instance"
                local okParent, parent = pcall(function() return node.Parent end)
                node = okParent and parent or nil
            end
            local result = {}
            for i = #names, 1, -1 do result[#result + 1] = names[i] end
            return table.concat(result, ".")
        end
    end

    if k=='GetDebugId'     then return function() return tostring(math.random(1e5,1e6)) end end
    if k=='IsDescendantOf' then return function(s2, ancestor) return _instance_descendant(s2, ancestor) and s2 ~= ancestor end end
    if k=='IsAncestorOf' then return function(s2, descendant) return _instance_descendant(descendant, s2) and s2 ~= descendant end end
    if k=='SetAttribute' then
        return function(s2, name, value)
            local attrs = rawget(s2, '__attributes')
            if not attrs then attrs = {}; rawset(s2, '__attributes', attrs) end
            local attrName = tostring(name)
            local old = attrs[attrName]
            attrs[attrName] = value
            if old ~= value then
                _get_sig(s2, '__acs:' .. attrName):Fire()
                _get_sig(s2, 'AttributeChanged'):Fire(attrName)
            end
        end
    end
    if k=='GetAttribute' then
        return function(s2, name)
            local attrs = rawget(s2, '__attributes')
            return attrs and attrs[tostring(name)] or nil
        end
    end
    if k=='GetAttributes' then
        return function(s2)
            local result = {}
            local attrs = rawget(s2, '__attributes') or {}
            for name, value in pairs(attrs) do result[name] = value end
            return result
        end
    end
    if k=='HasTag'         then return function() return false end end
    if k=='AddTag' or k=='RemoveTag' then return function() end end
    if k=='GetActor'       then return function() return nil end end
    local cls = rawget(self, 'ClassName') or ''
    if cls == 'BindableEvent' and k == 'Event' then
        return _get_sig(self, 'Event')
    end
    if cls == 'BindableEvent' and k == 'Fire' then
        return function(self2, ...)
            return _get_sig(self2, 'Event'):Fire(...)
        end
    end
    if cls == 'BindableFunction' and k == 'Invoke' then
        return function(self2, ...)
            local callback = rawget(self2, 'OnInvoke')
            if type(callback) == 'function' then
                return callback(...)
            end
            return nil
        end
    end
    if _BASE_EVT[k] then return _get_sig(self, k) end
    -- class-specific lookup
    if cls == "Animator" and k == "LoadAnimation" then
        return function(_, animation)
            local track = _build_instance("AnimationTrack")
            rawset(track, "Animation", animation)
            rawset(track, "_is_playing", false)
            rawset(track, "_time_position", 0)
            rawset(track, "_started_at", 0)
            rawset(track, "_speed", 1)
            rawset(track, "Length", 1)
            rawset(track, "Play", function(self2, _, _, speed)
                rawset(self2, "_speed", tonumber(speed) or 1)
                rawset(self2, "_started_at", _sim_clock)
                rawset(self2, "_time_position", 0)
                rawset(self2, "_is_playing", true)
            end)
            rawset(track, "Stop", function(self2)
                local elapsed = _sim_clock - (rawget(self2, "_started_at") or _sim_clock)
                rawset(self2, "_time_position", math.max(0, elapsed) * (rawget(self2, "_speed") or 1))
                rawset(self2, "_is_playing", false)
            end)
            rawset(track, "AdjustSpeed", function(self2, speed)
                local elapsed = _sim_clock - (rawget(self2, "_started_at") or _sim_clock)
                rawset(self2, "_time_position", math.max(0, elapsed) * (rawget(self2, "_speed") or 1))
                rawset(self2, "_started_at", _sim_clock)
                rawset(self2, "_speed", tonumber(speed) or 1)
            end)
            return track
        end
    end
    if cls == "AnimationTrack" then
        if k == "IsPlaying" then return rawget(self, "_is_playing") == true end
        if k == "TimePosition" then
            if rawget(self, "_is_playing") then
                local elapsed = _sim_clock - (rawget(self, "_started_at") or _sim_clock)
                return math.max(0, elapsed) * (rawget(self, "_speed") or 1)
            end
            return rawget(self, "_time_position") or 0
        end
        if k == "DidLoop" then return _get_sig(self, "DidLoop") end
        if k == "Ended" or k == "Stopped" or k == "KeyframeReached" then return _get_sig(self, k) end
    end
    if _API_MEMBER.EVENTS[k] then return _get_sig(self, k) end
    if _API_MEMBER.CALLBACKS[k] or _API_MEMBER.PROPERTIES[k] then return nil end
    if _API_MEMBER.METHODS[k] then return function() return nil end end
    local mems = _get_full_members(cls)
    local mt   = mems[k]
    if mt==1 then return function() return nil end end
    if mt==2 then return _get_sig(self, k) end
    return function() return nil end
end

local function _mk_instance(tbl)
    return setmetatable(tbl or {}, _fake_instance_mt)
end
local _BYPASS_NOT_CREATABLE = {
    Object = true, Instance = true, DataModel = true, PVInstance = true,
    BasePart = true, FormFactorPart = true, TriangleMeshPart = true, PartOperation = true,
    GuiBase = true, GuiBase2d = true, GuiBase3d = true, GuiObject = true, GuiButton = true,
    LayerCollector = true, ValueBase = true, Constraint = true, JointInstance = true,
    ServiceProvider = true, GenericSettings = true, UIBase = true, UIComponent = true,
    UILayout = true, UIGridStyleLayout = true, PostEffect = true, Light = true,
    DataModelMesh = true, Player = true, Workspace = true, CoreGui = true, CorePackages = true,
    Players = true, Lighting = true, ReplicatedStorage = true, ReplicatedFirst = true,
    ServerStorage = true, ServerScriptService = true, StarterGui = true,
    StarterPlayer = true, StarterPack = true, StarterGear = true, Terrain = true,
    SoundService = true, Teams = true, Chat = true, Debris = true, HttpService = true,
    CollectionService = true, MarketplaceService = true, PathfindingService = true,
    PhysicsService = true, ContextActionService = true, TeleportService = true,
    Stats = true, TestService = true, TextService = true, GuiService = true,
    TextChatService = true, AssetService = true, ContentProvider = true,
    InsertService = true, LocalizationService = true, PolicyService = true,
    MemoryStoreService = true, MessagingService = true, DataStoreService = true,
    AnalyticsService = true, BadgeService = true, VirtualInputManager = true,
    UserSettings = true, RunService = true, TweenService = true, UserInputService = true,
    VoiceChatService = true,
}

local function _bypass_new_instance(cls, parent)
    if type(cls) ~= "string" then
        error("invalid argument #1 to 'new' (string expected, got " .. type(cls) .. ")", 2)
    end
    if cls == "" or _BYPASS_NOT_CREATABLE[cls] or cls:match("Service$") or not _ROBLOX_SUPER[cls] then
        error('Unable to create an Instance of type "' .. cls .. '"', 2)
    end
    return _build_instance(cls, parent)
end

local function _bypass_from_existing(o)
    if type(o) ~= "table" or rawget(o, "ClassName") == nil or rawget(o, "__destroyed") then
        error("Unable to cast value to Object", 2)
    end
    local cls = rawget(o, "ClassName")
    local clone = _bypass_new_instance(cls, nil)
    rawset(clone, "Name", rawget(o, "Name") or cls)
    for key, value in pairs(o) do
        if key ~= "Parent" and key ~= "ClassName" and key ~= "Name" and key ~= "__attributes" and key ~= "__destroyed" and type(value) ~= "function" then
            rawset(clone, key, value)
        end
    end
    local srcAttrs = rawget(o, "__attributes")
    if type(srcAttrs) == "table" then
        local dstAttrs = {}
        for k, v in pairs(srcAttrs) do dstAttrs[k] = v end
        rawset(clone, "__attributes", dstAttrs)
    end
    return clone
end

-- Build a typed stub for any Roblox Instance class
_build_instance = function(cls, parent)
    local inst = setmetatable({
        ClassName = cls, Name = cls, Archivable = true,
    }, _fake_instance_mt)
    if cls == "Part" or cls == "MeshPart" or cls == "WedgePart" or cls == "CornerWedgePart" or cls == "TrussPart" or cls == "Seat" or cls == "VehicleSeat" or cls == "SpawnLocation" then
        rawset(inst, "Anchored", false)
        rawset(inst, "CanCollide", true)
        rawset(inst, "Transparency", 0)
    elseif cls == "Weld" or cls == "WeldConstraint" or cls == "Motor6D" or cls == "ManualWeld" or cls == "Snap" or cls == "Glue" or cls == "Motor" then
        rawset(inst, "Enabled", true)
    elseif cls == "IntValue" or cls == "NumberValue" then
        rawset(inst, "Value", 0)
    elseif cls == "StringValue" then
        rawset(inst, "Value", "")
    elseif cls == "BoolValue" then
        rawset(inst, "Value", false)
    end
    if parent ~= nil then _set_instance_parent(inst, parent) end
    local props = _ROBLOX_PROPS[cls]
    if props then for p in pairs(props) do rawset(inst, p, rawget(inst, p)) end end
    _grs_new_insts[inst] = cls
    local function findAncestor(self2, target, mode)
        local node = rawget(self2, "Parent")
        local depth = 0
        while node ~= nil and depth < 128 do
            depth = depth + 1
            local name = rawget(node, "Name")
            local className = rawget(node, "ClassName")
            if (mode == "name" and name == target)
               or (mode == "class" and className == target)
               or (mode == "isa" and type(node.IsA) == "function" and node:IsA(target)) then
                return node
            end
            node = rawget(node, "Parent")
        end
        return nil
    end
    rawset(inst, "FindFirstAncestor", function(self2, name) return findAncestor(self2, name, "name") end)
    rawset(inst, "FindFirstAncestorOfClass", function(self2, name) return findAncestor(self2, name, "class") end)
    rawset(inst, "FindFirstAncestorWhichIsA", function(self2, name) return findAncestor(self2, name, "isa") end)
    return inst
end
_G.Instance = _G.Instance or {}
_G.Instance.new = _bypass_new_instance
_G.Instance.fromExisting = _bypass_from_existing

-- EditableMesh stub with stateful vertex/face/normal/UV/color storage
local function _mk_editable_mesh()
    local _verts, _faces, _normals, _uvs, _colors = {}, {}, {}, {}, {}
    local _next_id = 0
    local function _nid() _next_id = _next_id + 1; return _next_id end
    local self = {}

    function self:AddVertex(pos)
        local id = _nid()
        _verts[id] = pos or {X=0,Y=0,Z=0}
        return id
    end
    function self:GetVertices()
        local t = {}
        for id in pairs(_verts) do t[#t+1] = id end
        table.sort(t); return t
    end
    function self:GetPosition(id) return _verts[id] or {X=0,Y=0,Z=0} end
    function self:SetPosition(id, pos) if id then _verts[id] = pos end end

    function self:AddFace(v1,v2,v3) local id=_nid();_faces[id]={v1,v2,v3};return id end
    function self:AddTriangle(v1,v2,v3) return self:AddFace(v1,v2,v3) end
    function self:GetFaces() local t={};for id in pairs(_faces) do t[#t+1]=id end;table.sort(t);return t end
    function self:GetFaceVertices(id) return _faces[id] or {} end
    function self:RemoveFace(id) _faces[id]=nil end

    function self:AddNormal(n) local id=_nid();_normals[id]=n or {X=0,Y=1,Z=0};return id end
    function self:GetNormal(id) return _normals[id] or {X=0,Y=1,Z=0} end
    function self:SetNormal(id,n) if id then _normals[id]=n end end
    function self:ResetNormal(id) _normals[id]={X=0,Y=1,Z=0} end
    function self:GetNormals() local t={};for id in pairs(_normals) do t[#t+1]=id end;table.sort(t);return t end

    function self:AddUV(uv) local id=_nid();_uvs[id]=uv or {X=0,Y=0};return id end
    function self:GetUV(id) return _uvs[id] or {X=0,Y=0} end
    function self:SetUV(id,uv) if id then _uvs[id]=uv end end
    function self:GetUVs() local t={};for id in pairs(_uvs) do t[#t+1]=id end;table.sort(t);return t end

    function self:AddColor(c) local id=_nid();_colors[id]=c or {R=1,G=1,B=1};return id end
    function self:GetColor(id) return _colors[id] or {R=1,G=1,B=1} end
    function self:SetColor(id,c) if id then _colors[id]=c end end
    function self:GetColors() local t={};for id in pairs(_colors) do t[#t+1]=id end;table.sort(t);return t end
    function self:GetColorAlpha() return 1 end
    function self:SetColorAlpha() end

    function self:GetSize() local v=_G.Vector3;return v and v.new(0,0,0) or {X=0,Y=0,Z=0} end
    function self:GetCenter() local v=_G.Vector3;return v and v.new(0,0,0) or {X=0,Y=0,Z=0} end
    function self:Clear() _verts,_faces,_normals,_uvs,_colors,_next_id={},{},{},{},{},0 end
    function self:Destroy() self:Clear() end

    function self:GetAdjacentVertices() return {} end
    function self:GetAdjacentFaces() return {} end
    function self:GetVertexFaces() return {} end
    function self:GetVertexNormals() return {} end
    function self:GetVertexUVs() return {} end
    function self:GetVertexColors() return {} end
    function self:GetFaceNormals() return {} end
    function self:GetFaceUVs() return {} end
    function self:GetFaceColors() return {} end
    function self:GetVerticesWithNormal() return {} end
    function self:GetVerticesWithUV() return {} end
    function self:GetVerticesWithColor() return {} end
    function self:GetFacesWithNormal() return {} end
    function self:GetFacesWithUV() return {} end
    function self:GetFacesWithColor() return {} end
    function self:FindClosestVertex() return nil end
    function self:FindVerticesWithinSphere(pos, r)
        local t={};if not(pos and r) then return t end
        for id,vp in pairs(_verts) do
            local dx=(vp.X or 0)-(pos.X or 0)
            local dy=(vp.Y or 0)-(pos.Y or 0)
            local dz=(vp.Z or 0)-(pos.Z or 0)
            if math.sqrt(dx*dx+dy*dy+dz*dz)<=r then t[#t+1]=id end
        end
        return t
    end
    function self:FindClosestPointOnSurface()
        local v=_G.Vector3;return v and v.new(0,0,0) or {X=0,Y=0,Z=0},nil,0
    end
    function self:MergeVertices() end
    function self:Triangulate() end
    function self:RemoveUnused() end
    function self:RaycastLocal() return nil end
    function self:IdDebugString(id) return tostring(id) end

    function self:GetBones() return {} end
    function self:GetBoneByName() return nil end
    function self:GetBoneName() return "" end
    function self:GetBoneParent() return -1 end
    function self:GetBoneCFrame() local v=_G.Vector3;return {Position=v and v.new(0,0,0) or {X=0,Y=0,Z=0}} end
    function self:SetBoneCFrame() end
    function self:GetBoneIsVirtual() return false end
    function self:SetBoneIsVirtual() end
    function self:SetBoneName() end
    function self:SetBoneParent() end
    function self:AddBone() return _nid() end
    function self:RemoveBone() end
    function self:GetVertexBones() return {} end
    function self:GetVertexBoneWeights() return {} end
    function self:SetVertexBones() end
    function self:SetVertexBoneWeights() end

    function self:GetFacsPoses() return {} end
    function self:GetFacsPose() return {} end
    function self:SetFacsPose() end
    function self:GetFacsCorrectivePoses() return {} end
    function self:GetFacsCorrectivePose() return {} end
    function self:SetFacsCorrectivePose() end
    function self:SetFacsBonePose() end
    function self:SetFaceVertices() end
    function self:SetFaceNormals() end
    function self:SetFaceUVs() end
    function self:SetFaceColors() end
    function self:GetVertexFaceNormal() return 0 end
    function self:SetVertexFaceNormal() end
    function self:GetVertexFaceUV() return 0 end
    function self:SetVertexFaceUV() end
    function self:GetVertexFaceColor() return 0 end
    function self:SetVertexFaceColor() end

    self.ClassName = "EditableMesh"
    self.Name = "EditableMesh"
    return setmetatable(self, {
        __metatable = "EditableMesh",
        __tostring  = function() return "EditableMesh" end,
        __index     = self,
        __newindex  = function(t,k,v) rawset(t,k,v) end,
    })
end

