-- EditableMesh factory: full vertex store so AssetService:CreateEditableMesh() passes checks
local function _make_editable_mesh()
    local _verts  = {}
    local _nextId = 1
    local _emesh  = {}
    _emesh.ClassName  = "EditableMesh"
    _emesh.AddVertex  = function(_, pos)
        local id = _nextId
        _verts[id] = pos
        _nextId = _nextId + 1
        return id
    end
    _emesh.GetVertices = function()
        local out = {}
        for id in pairs(_verts) do out[#out + 1] = id end
        return out
    end
    _emesh.GetPosition  = function(_, id) return _verts[id] or {X=0,Y=0,Z=0} end
    _emesh.SetPosition  = function(_, id, pos) _verts[id] = pos end
    _emesh.AddFace      = function() end
    _emesh.AddNormal    = function() end
    _emesh.AddUV        = function() end
    _emesh.AddColor     = function() end
    _emesh.AddTriangle  = function() end
    _emesh.RemoveFace   = function() end
    _emesh.RemoveUnused = function() end
    _emesh.GetSize      = function() return {X=0,Y=0,Z=0} end
    _emesh.GetCenter    = function() return {X=0,Y=0,Z=0} end
    _emesh.GetFaces     = function() return {} end
    _emesh.Clear        = function() _verts = {}; _nextId = 1 end
    _emesh.Destroy      = function() _verts = {}; _nextId = 1 end
    return setmetatable(_emesh, {
        __metatable = "Instance",
        __tostring  = function() return "EditableMesh" end,
        __newindex  = function(s, k, v) rawset(s, k, v) end,
        __index     = function(_, k) return function() return nil end end,
    })
end

do
    local _as = _mk_instance({ClassName = "AssetService", Name = "AssetService"})
    rawset(_as, "CreateEditableMesh",       function() return _make_editable_mesh() end)
    rawset(_as, "CreateEditableMeshAsync",  function() return _make_editable_mesh() end)
    rawset(_as, "CreateEditableImage",      function() return _mk_instance({ClassName="EditableImage"}) end)
    rawset(_as, "CreateEditableImageAsync", function() return _mk_instance({ClassName="EditableImage"}) end)
    rawset(_as, "CreatePlaceAsync",         function() return 0 end)
    rawset(_as, "GetBundleDetailsAsync",    function() return {} end)
    rawset(_as, "GetGamePlacesAsync",       function()
        return _mk_instance({ClassName="StandardPages",IsFinished=true,
            GetCurrentPage=function()return{}end,
            AdvanceToNextPageAsync=function()end})
    end)
    rawset(_as, "LoadAssetAsync",           function() return _mk_instance({ClassName="Model"}) end)
    rawset(_as, "SavePlaceAsync",           function() return 0 end)
    _fake_services["AssetService"] = _as
end

local function _get_service(_, name)
    local s = _fake_services[name]
    if s then return s end
    s = _build_instance(name, nil)
    rawset(s, 'Name', name)
    _fake_services[name] = s
    return s
end

do
    local _BYPASS_IDENTITY = "_RBX_LP_"
    local _pl_svc = _fake_services.Players

    local _lp = rawget(_pl_svc, "LocalPlayer")
    if type(_lp) ~= "table" then
        _lp = _mk_instance({
            Name        = _BYPASS_IDENTITY,
            DisplayName = _BYPASS_IDENTITY,
            UserId      = 0,
        })
        rawset(_pl_svc, "LocalPlayer", _lp)
    else
        if rawget(_lp, "Name") == nil then
            rawset(_lp, "Name", _BYPASS_IDENTITY)
        end
        if rawget(_lp, "DisplayName") == nil then
            rawset(_lp, "DisplayName", _BYPASS_IDENTITY)
        end
    end

    local _character = rawget(_lp, "Character")
    if type(_character) ~= "table" then
        _character = _build_instance("Model")
        rawset(_character, "Name", "Character")
        _set_instance_parent(_character, _lp)
        rawset(_lp, "Character", _character)
    end

    local _character_color_mt = { __type = "Color3", __metatable = "Color3" }
    local _character_vector3_mt = { __type = "Vector3", __metatable = "Vector3" }
    local _character_cframe_mt = { __type = "CFrame", __metatable = "CFrame" }
    local _character_enum_mt = { __type = "EnumItem", __metatable = "EnumItem" }
    local _character_color = setmetatable({ R = 163 / 255, G = 162 / 255, B = 165 / 255 }, _character_color_mt)
    local _character_material = setmetatable({ Name = "Plastic", Value = 256, EnumType = "Material" }, _character_enum_mt)
    local function _character_vector3(x, y, z)
        x, y, z = x or 0, y or 0, z or 0
        return setmetatable({
            X = x, Y = y, Z = z,
            Magnitude = math.sqrt(x * x + y * y + z * z),
        }, _character_vector3_mt)
    end
    local function _character_cframe(x, y, z)
        x, y, z = x or 0, y or 0, z or 0
        return setmetatable({
            X = x, Y = y, Z = z,
            Position = _character_vector3(x, y, z),
        }, _character_cframe_mt)
    end
    local function _character_part(name, x, y, z)
        local part = _build_instance("Part", _character)
        rawset(part, "Name", name)
        rawset(part, "Color", _character_color)
        rawset(part, "Size", _character_vector3(1, 1, 1))
        rawset(part, "CFrame", _character_cframe(x, y, z))
        rawset(part, "Material", _character_material)
        return part
    end
    _character_part("Head", 0, 6.5, 0)
    _character_part("UpperTorso", 0, 5.5, 0)
    _character_part("LeftUpperArm", -1.5, 5.5, 0)
    _character_part("RightUpperArm", 1.5, 5.5, 0)
    _character_part("LeftUpperLeg", -0.5, 3.5, 0)
    _character_part("RightUpperLeg", 0.5, 3.5, 0)

    local _humanoid = _character:FindFirstChild("Humanoid")
    if _humanoid == nil then
        _humanoid = _build_instance("Humanoid", _character)
        rawset(_humanoid, "Name", "Humanoid")
    end
    local _animator = _humanoid:FindFirstChild("Animator")
    if _animator == nil then
        _animator = _build_instance("Animator", _humanoid)
        rawset(_animator, "Name", "Animator")
    end

    local function characterChild(self2, name)
        if name == "Animate" then return _grs_anim end
        for _, child in ipairs(_instance_children[self2] or {}) do
            if rawget(child, "Name") == name or rawget(child, "ClassName") == name then return child end
        end
        return nil
    end
    rawset(_character, "FindFirstChild", characterChild)
    rawset(_character, "FindFirstChildOfClass", function(self2, className)
        for _, child in ipairs(_instance_children[self2] or {}) do
            if rawget(child, "ClassName") == className then return child end
        end
        return nil
    end)
    rawset(_character, "FindFirstChildWhichIsA", function(self2, className)
        for _, child in ipairs(_instance_children[self2] or {}) do
            if type(child.IsA) == "function" and child:IsA(className) then return child end
        end
        return nil
    end)
    rawset(_character, "WaitForChild", characterChild)

    rawset(_pl_svc, "GetNameFromUserIdAsync", function(_, _userId)
        local lp = rawget(_pl_svc, "LocalPlayer")
        if type(lp) == "table" then
            return rawget(lp, "Name") or _BYPASS_IDENTITY
        end
        return _BYPASS_IDENTITY
    end)

    rawset(_pl_svc, "GetUserIdFromNameAsync", function(_, _name)
        local lp = rawget(_pl_svc, "LocalPlayer")
        if type(lp) == "table" then
            return rawget(lp, "UserId") or 0
        end
        return 0
    end)

    local _prev_reset = _G._bypassOnReset
    _G._bypassOnReset = function()
        if type(_prev_reset) == "function" then pcall(_prev_reset) end
        local g  = _G.game
        if type(g) ~= "table" then return end
        local ok, pl = pcall(function() return g:GetService("Players") end)
        if not ok or type(pl) ~= "table" then return end

        if type(rawget(pl, "LocalPlayer")) ~= "table" then
            rawset(pl, "LocalPlayer", _mk_instance({
                Name        = _BYPASS_IDENTITY,
                DisplayName = _BYPASS_IDENTITY,
                UserId      = 0,
            }))
        end

        rawset(pl, "GetNameFromUserIdAsync", function(_, _uid)
            local lp2 = rawget(pl, "LocalPlayer")
            if type(lp2) == "table" then
                return rawget(lp2, "Name") or _BYPASS_IDENTITY
            end
            return _BYPASS_IDENTITY
        end)
        rawset(pl, "GetUserIdFromNameAsync", function(_, _nm)
            local lp2 = rawget(pl, "LocalPlayer")
            if type(lp2) == "table" then
                return rawget(lp2, "UserId") or 0
            end
            return 0
        end)
    end
end

_G._RTYPE = _G._RTYPE or setmetatable({}, { __mode = "k" })

typeof = typeof or function(v)
    if v == nil then return "nil" end
    local t = type(v)
    if t == "boolean"  then return "boolean"  end
    if t == "number"   then return "number"   end
    if t == "string"   then return "string"   end
    if t == "function" then return "function" end
    if t == "thread"   then return "thread"   end
    if t == "userdata" then
        local mt = getmetatable(v)
        if mt == "Instance" or mt == _fake_instance_mt then return "Instance" end
        if mt and type(mt.__type) == "string" then return mt.__type end
        return "userdata"
    end
    if t == "table" then
        if _G._RTYPE and _G._RTYPE[v] then return _G._RTYPE[v] end
        local mt = getmetatable(v)
        if mt then
            if mt == "Instance" or mt == _fake_instance_mt then return "Instance" end
            if type(mt) == "table" then
                if mt.__metatable == "Instance"  then return "Instance" end
                if type(mt.__type) == "string"   then return mt.__type  end
                local ok_ts, s = pcall(tostring, v)
                if ok_ts and type(s) == "string" then
                    local _roblox_types = {
                        "Vector3","Vector2","CFrame","Color3","UDim2","UDim",
                        "BrickColor","TweenInfo","NumberSequence","ColorSequence",
                        "NumberRange","Rect","Ray","Axes","Faces","Region3",
                        "Region3int16","Vector3int16","Vector2int16",
                        "PhysicalProperties","RaycastResult","EnumItem",
                        "RBXScriptSignal","RBXScriptConnection","Random",
                        "PathWaypoint","Font","FloatCurveKey","RotationCurveKey",
                        "OverlapParams","RaycastParams","SharedTable",
                    }
                    for _, rtn in ipairs(_roblox_types) do
                        if s:sub(1, #rtn) == rtn then return rtn end
                    end
                end
            end
        end
        return "table"
    end
    return t
end

do
    local _raw_type = type
    type = function(v)
        local t = _raw_type(v)
        if t ~= "table" then return t end
        local ok, mt = pcall(getmetatable, v)
        if ok and (mt == _fake_instance_mt or mt == "Instance") then
            return "userdata"
        end
        return t
    end
end

do
    local _ei_meta_data = setmetatable({}, {__mode = "k"})
    local function _mkEnumItem(enum_type_ref, ename, iname, ival)
        local mt = {
            __type      = "EnumItem",
            __metatable = "EnumItem",
            __tostring  = function() return "Enum."..ename.."."..iname end,
            __newindex  = function() error("EnumItem is read-only", 2) end,
            __eq        = function(a, b)
                if rawequal(a, b) then return true end
                local da, db = _ei_meta_data[a], _ei_meta_data[b]
                if da and db then
                    return da.et_ref[1] == db.et_ref[1] and da.ename == db.ename and da.iname == db.iname and da.ival == db.ival
                end
                return false
            end,
            __index = function(_, k)
                if k == "Name"     then return iname end
                if k == "Value"    then return ival  end
                if k == "EnumType" then return enum_type_ref[1] end
                return nil
            end,
        }
        local obj = setmetatable({}, mt)
        _ei_meta_data[obj] = { et_ref = enum_type_ref, ename = ename, iname = iname, ival = ival }
        if _G._RTYPE then _G._RTYPE[obj] = "EnumItem" end
        return obj
    end
    local function _mkEnumType(ename, defs)
        local by_name, by_val, list = {}, {}, {}
        local et_holder = { false }
        local et_mt = {
            __type      = "Enum",
            __metatable = "Enum",
            __tostring  = function() return "Enum."..ename end,
            __call      = function(_, ...) return list end,
            __index = function(_, k)
                if k == "GetEnumItems" then return function(_) return list end end
                return by_name[k]
            end,
            __newindex = function() error("Cannot modify Enum."..ename, 2) end,
        }
        local et = setmetatable({}, et_mt)
        et_holder[1] = et
        for name, value in pairs(defs) do
            local item = _mkEnumItem(et_holder, ename, name, value)
            by_name[name]   = item
            by_val[value]   = item
            list[#list + 1] = item
        end
        return et
    end
