        if #n >= 12 and n:find("0000") then return true end
        if n:find("XXXXX") or n:find("ZZZZZ") or n:find("AAAAA") then return true end
        if n:match("[A-Z0-9][A-Z0-9][A-Z0-9][A-Z0-9][A-Z0-9][A-Z0-9][A-Z0-9][A-Z0-9]$") and
