-- Static only: format was independently validated against the custom base85-XOR loader fixture.
do
    local has_static_b85_xor = src:find("local function b85dec", 1, true)
        and src:find("local function xdec", 1, true)
        and src:find("local payload=", 1, true)
        and src:find("local c1=", 1, true)
        and src:find("local c2=", 1, true)
        and src:find("local k=", 1, true)
    if has_static_b85_xor then
        local payload = src:match('local%s+payload%s*=%s*"([^"]*)"')
        local c1 = src:match('local%s+c1%s*=%s*"([^"]*)"')
        local c2 = src:match('local%s+c2%s*=%s*"([^"]*)"')
        local key = src:match('local%s+k%s*=%s*"([^"]*)"')
        local function b85decode(data, alphabet)
            if type(data) ~= "string" or type(alphabet) ~= "string"
                or #alphabet < 32 or #alphabet > 128 or #data > 16384 then
                return nil
            end
            local lookup = {}
            for index = 1, #alphabet do
                local ch = alphabet:sub(index, index)
                if lookup[ch] ~= nil then return nil end
                lookup[ch] = index - 1
            end
            local out, pos, base = {}, 1, #alphabet
            while pos <= #data do
                local chunk = data:sub(pos, pos + 4)
                local length = #chunk
                if length == 1 then return nil end
                local bytes = (length == 2 and 1) or (length == 3 and 2) or (length == 4 and 3) or 4
                local value = 0
                for index = 1, length do
                    local digit = lookup[chunk:sub(index, index)]
                    if digit == nil then return nil end
                    value = value * base + digit
                end
                local part = {}
                for index = bytes, 1, -1 do
                    part[index] = string.char(value % 256)
                    value = math.floor(value / 256)
                end
                out[#out + 1] = table.concat(part)
                pos = pos + length
            end
            return table.concat(out)
        end
        local function xordecode(data, xor_key)
            if type(data) ~= "string" or type(xor_key) ~= "string" or #xor_key == 0 then return nil end
            local out = {}
            for index = 1, #data do
                out[index] = string.char(bit32.bxor(
                    string.byte(data, index),
                    string.byte(xor_key, ((index - 1) % #xor_key) + 1)
                ))
            end
            return table.concat(out)
        end
        if payload and c1 and c2 and key then
            local stage1 = b85decode(payload, c2)
            local stage2 = stage1 and xordecode(stage1, key .. "_2")
            local stage3 = stage2 and b85decode(stage2, c1)
            local decoded = stage3 and xordecode(stage3, key)
            if decoded and #decoded > 0 and #decoded <= 65536
                and decoded:match("^[%z\1-\127]+$") and decoded:find("[%a_]", 1) then
                dump_and_exit(decoded, "static-base85-xor")
            end
        end
    end
end

