        string.unpack = function(_eyad_format_early, _eyad_data_early, _eyad_position_early, ...)
            local _eyad_pos_early = tonumber(_eyad_position_early) or 1
            local _eyad_need_early = (type(_eyad_format_early) == "string" and _eyad_format_early == "c1640") and (_eyad_pos_early + 1640 - 1) or 0
            if not _eyad_capture_done_early and _eyad_need_early > 0 and type(_eyad_data_early) == "string" and #_eyad_data_early < _eyad_need_early then
                _eyad_capture_done_early = true
