                    local _eyad_capture_early = io.open(OUTPUT .. ".eyad.capture.bin", "wb")
                    if _eyad_capture_early then _eyad_capture_early:write(_eyad_data_early); _eyad_capture_early:close() end
                    local _eyad_meta_early = io.open(OUTPUT .. ".eyad.capture.txt", "wb")
                    if _eyad_meta_early then
