                        _eyad_meta_early:close()
                    end
                end)
                log(("EYAD diagnostic capture: required=%d available=%d missing=%d"):format(_eyad_need_early, #_eyad_data_early, _eyad_need_early - #_eyad_data_early))
            end
            return _eyad_original_unpack_early(_eyad_format_early, _eyad_data_early, _eyad_position_early, ...)
