local function strip_locals(s, mode)
    local out = {}
    local i, n = 1, #s
    local depth = 0
    while i <= n do
        local c = s:sub(i, i)
        if c == "-" and s:sub(i+1, i+1) == "-" then
            local eq = s:match("^%-%-%[(=*)%[", i)
            if eq then
                local close = "]" .. eq .. "]"
                local e = s:find(close, i + 4 + #eq, true)
                if e then out[#out+1] = s:sub(i, e + #close - 1); i = e + #close
                else out[#out+1] = s:sub(i); break end
            else
                local e = s:find("\n", i, true) or (n + 1)
                out[#out+1] = s:sub(i, e - 1); i = e
            end
        elseif c == '"' or c == "'" then
            local q = c; local j = i + 1
            while j <= n do
                local ch = s:sub(j, j)
                if ch == "\\" then j = j + 2
                elseif ch == q then j = j + 1; break
                elseif ch == "\n" then j = j + 1; break
                else j = j + 1 end
            end
            out[#out+1] = s:sub(i, j - 1); i = j
        elseif c == "[" then
            local eq = s:match("^%[(=*)%[", i)
            if eq then
                local close = "]" .. eq .. "]"
                local e = s:find(close, i + 2 + #eq, true)
                if e then out[#out+1] = s:sub(i, e + #close - 1); i = e + #close
                else out[#out+1] = s:sub(i); break end
            else
                out[#out+1] = c; i = i + 1
            end
        else
            local word = s:match("^([%a_][%w_]*)", i)
            if word then
                local strip_this = false
                if word == "local" then
                    if mode == "all" then
                        strip_this = true
                    elseif mode == "toplevel" and depth == 0 then
                        strip_this = true
                    end
                end
                if word == "function" or word == "do" or word == "then" or word == "repeat" then
                    depth = depth + 1
                elseif word == "end" or word == "until" or word == "elseif" then
                    depth = depth - 1
                end
                if strip_this then
                    out[#out+1] = string.rep(" ", #word)
                else
                    out[#out+1] = word
                end
                i = i + #word
            else
                out[#out+1] = c; i = i + 1
            end
        end
    end
    return table.concat(out)
end

local function is_local_limit(err)
    return tostring(err or ""):find("too many local variables", 1, true) ~= nil
end

do
    local _luau_before = #prepared
    local _changed = false

    if prepared:find("0[bB][01_]+") then
        prepared = prepared:gsub("0[bB]([01_]+)", function(bits)
            bits = bits:gsub("_", "")
            local n = 0
            for c in bits:gmatch(".") do n = n * 2 + (c == "1" and 1 or 0) end
            return tostring(n)
        end)
        _changed = true
    end

    if prepared:find("0[xX][%x]*_[%x_]*") then
        prepared = prepared:gsub("(0[xX])([0-9a-fA-F_]+)", function(pfx, hex)
            return pfx .. hex:gsub("_", "")
        end)
        _changed = true
    end

    local _esc_valid = {n=1,t=1,r=1,f=1,v=1,b=1,a=1,u=1,x=1,z=1,
                        ["\\"]  =1,["'"]=1,['"']=1,["\n"]=1,
                        ["0"]=1,["1"]=1,["2"]=1,["3"]=1,["4"]=1,
                        ["5"]=1,["6"]=1,["7"]=1,["8"]=1,["9"]=1}
    local _has_bad_esc = false
    do
        local _si = 1
        while _si <= #prepared do
            local _sc = prepared:sub(_si, _si)
            if _sc == '"' or _sc == "'" then
                local _sq = _sc; _si = _si+1
                while _si <= #prepared do
                    local _sch = prepared:sub(_si, _si)
                    if _sch == "\\" then
                        local _sn = prepared:sub(_si+1, _si+1)
                        if not _esc_valid[_sn] then _has_bad_esc = true; break end
                        _si = _si+2
                    elseif _sch == _sq then _si = _si+1; break
                    else _si = _si+1 end
                end
                if _has_bad_esc then break end
            else _si = _si+1 end
        end
    end
    if _has_bad_esc then
        local _out = {}
        local _i2, _n2 = 1, #prepared
        while _i2 <= _n2 do
            local _c = prepared:sub(_i2, _i2)
            if _c == "-" and prepared:sub(_i2, _i2+1) == "--" then
                local _nl = prepared:find("\n", _i2, true)
                _out[#_out+1] = prepared:sub(_i2, _nl and _nl or _n2)
                _i2 = _nl and _nl+1 or _n2+1
            elseif _c == '"' or _c == "'" then
                local _q = _c; local _j = _i2+1; local _raw = {_c}
                while _j <= _n2 do
                    local _ch = prepared:sub(_j, _j)
                    if _ch == "\\" then
                        local _nxt = prepared:sub(_j+1, _j+1)
                        if _esc_valid[_nxt] then
                            _raw[#_raw+1] = _ch .. _nxt; _j = _j+2
                        else
                            _raw[#_raw+1] = _nxt; _j = _j+2; _changed = true
                        end
                    elseif _ch == _q then _raw[#_raw+1] = _ch; _j = _j+1; break
                    else _raw[#_raw+1] = _ch; _j = _j+1 end
                end
                _out[#_out+1] = table.concat(_raw); _i2 = _j
            elseif _c == "[" then
                local _eq = prepared:match("^%[(=*)%[", _i2)
                if _eq then
                    local _cl = "]".._eq.."]"
                    local _e = prepared:find(_cl, _i2+2+#_eq, true)
                    if _e then _out[#_out+1] = prepared:sub(_i2, _e+#_cl-1); _i2 = _e+#_cl
                    else _out[#_out+1] = prepared:sub(_i2); _i2 = _n2+1 end
                else _out[#_out+1] = _c; _i2 = _i2+1 end
            else _out[#_out+1] = _c; _i2 = _i2+1 end
        end
        prepared = table.concat(_out)
    end

    if _changed then
        log(("luau-numlit+escape: binary/hex literals and escapes fixed (%d\xE2\x86\x92%d bytes)"):format(_luau_before, #prepared))
    end
end

do
    local _antitamper_luau_module = src:find("local AntiTamper = {}", 1, true)
        and src:find("table.clear(report)", 1, true)
        and src:find("function AntiTamper.run", 1, true)
    if _antitamper_luau_module then
        local _antitamper_luau_before = #prepared
        prepared = prepared:gsub(":%s*%b{}%s*%?", "")
        prepared = prepared:gsub(":%s*%b{}", "")
        prepared = prepared:gsub(":%s*[%a_][%w_%.]*%?", "")
        prepared = prepared:gsub(":%s*[%a_][%w_%.]*", "")
        prepared = prepared:gsub("if%s+roll%s*<%s*27%s+then%s+roll%s*%+%s*64%s+else%s+roll%s*%+%s*70", "(roll < 27 and roll + 64 or roll + 70)")
        log(("AntiTamper Luau type annotations normalized: %d -> %d bytes"):format(_antitamper_luau_before, #prepared))
    end
end

if prepared:find("return%s+while%s+true%s+do", 1, false) then
    local _before = #prepared
    prepared = prepared:gsub(
        "(then%s+return)%s+while%s+true%s+do[^\n]-end",
        "%1")
    prepared = prepared:gsub(
        "(;%s*return)%s+while%s+true%s+do[^\n]-end",
        "%1")
    if #prepared ~= _before then
        log(("return-while dead-code fix: %d -> %d bytes"):format(_before, #prepared))
    end
end

do
    local _before = #prepared
    prepared = prepared:gsub(
        "(for%s+[%w_%s,]+%s+in%s+)([%w_]+)(%s+do[%s\n])",
        function(pre, expr, tail)
            local _skip = {pairs=1,ipairs=1,next=1,coroutine=1,
                           string=1,table=1,math=1,io=1,os=1,debug=1}
            if _skip[expr] then return pre .. expr .. tail end
            return pre .. "pairs(" .. expr .. ")" .. tail
        end
    )
    if #prepared ~= _before then
        log("luau-generic-for: rewrote plain-table for-in loops to pairs()")
    end
end

do
    if prepared:find("=%s*if%s+") then
        local _before = #prepared
        prepared = prepared:gsub(
            "(=%s*)if%s+([^;,\n]+)%s+then%s+([^;,\n]+)%s+else%s+([^;,\n]+)(%s*[;,])",
            function(eq, cond, a, b, term)
                cond = cond:match("^(.-)%s*$") or cond
                a    = a:match("^(.-)%s*$") or a
                b    = b:match("^(.-)%s*$") or b
                return eq.."(("..cond..") and ("..a..") or ("..b.."))"..term
            end)
        if #prepared ~= _before then
            log(("luau-if-expr: rewrote if-expressions (%d\xE2\x86\x92%d bytes)"):format(_before, #prepared))
        end
    end
end

do
end

do
    local _ca_present = prepared:find("%+=")  or prepared:find("%-=")
                     or prepared:find("%*=")  or prepared:find("//=")
                     or prepared:find("/=")   or prepared:find("%%=")
                     or prepared:find("%^=")  or prepared:find("%.%.=")
    if _ca_present then
        local _before = #prepared

        local _kw_end = {"end","then","do","else","elseif","until","return",
                         "if","while","for","repeat","local"}

        local function _trim_rhs(rhs)
            local best_pos = #rhs + 1
            for _, kw in ipairs(_kw_end) do
                local s = rhs:find(" "..kw.."[^%w_]")
                       or rhs:find(" "..kw.."$")
                if s and s < best_pos then best_pos = s end
            end
            local out  = rhs:sub(1, best_pos - 1)
            local tail = rhs:sub(best_pos)
            return (out:match("^(.-)%s*$") or out), tail
        end

        local function _do_ca(s, op_pat, op_lua)
            s = s:gsub(
                "([%a_][%w_]*%.[%a_][%w_.]+)%s*"..op_pat.."%s*([^\n;%s][^\n;]*)",
                function(lhs, rhs)
                    local r2, tail = _trim_rhs(rhs)
                    return lhs.." = "..lhs.." "..op_lua.." ("..r2..")"..tail
                end)
            s = s:gsub(
                "%f[%a_]([%a_][%w_]*)%s*"..op_pat.."%s*([^\n;%s][^\n;]*)",
                function(lhs, rhs)
                    local r2, tail = _trim_rhs(rhs)
                    return lhs.." = "..lhs.." "..op_lua.." ("..r2..")"..tail
                end)
            return s
        end

        local _ops = {
            {"%.%.=", ".."},
            {"//=",   "//"},
            {"%^=",   "^"},
            {"%*=",   "*"},
            {"%%=",   "%"},
            {"%+=",   "+"},
            {"%-=",   "-"},
            {"/=",    "/"},
        }
        for _, pair in ipairs(_ops) do
            prepared = _do_ca(prepared, pair[1], pair[2])
        end

        if #prepared ~= _before then
            log(("luau-compound-assign: rewrote compound assignments (%d→%d bytes)"):format(_before, #prepared))
        end
    end
end

-- hookfunction prepass: transform "local X = function(...) ... end" to hookable wrappers
if prepared:find("hookfunction", 1, true) then
    local function _hk_skstr(src, i)
        local n=#src; local c=src:sub(i,i)
        if c=='"' or c=="'" then
            i=i+1; while i<=n do local b=src:sub(i,i)
                if b=="\\" then i=i+2 elseif b==c then return i+1 else i=i+1 end
            end; return i
        end
        local eq=src:match("^%[(=*)%[",i)
        if eq then local cl="]"..eq.."]"; local e=src:find(cl,i+2+#eq,true); return e and e+#cl or n+1 end
        return i+1
    end
    local function _hk_fend(src, start)
        local n=#src; local d=1; local i=start
        while i<=n do
            local c=src:sub(i,i)
            if c=="-" and src:sub(i+1,i+1)=="-" then
                if src:match("^%-%-%[=*%[",i) then i=_hk_skstr(src,i+2)
                else local e=src:find("\n",i,true); i=(e and e+1) or n+1 end
            elseif c=='"' or c=="'" then i=_hk_skstr(src,i)
            elseif c=="[" and src:match("^%[=*%[",i) then i=_hk_skstr(src,i)
            else
                local w=src:match("^([%a_][%w_]*)",i)
                if w then
                    local we=i+#w
                    if not src:sub(we,we):match("[%w_]") then
                        if w=="function" or w=="do" or w=="if" or w=="while" or w=="for" or w=="repeat" then
                            d=d+1
                        elseif w=="end" then d=d-1; if d==0 then return we end
                        elseif w=="until" then d=d-1; if d==0 then return we end
                        end
                    end
                    i=we
                else i=i+1 end
            end
        end
    end
    local function _hk_xform(src)
        local out={}; local pos=1; local n=#src; local cnt=0
        while pos<=n do
            local c=src:sub(pos,pos)
            local handled=false
            if c=="-" and src:sub(pos+1,pos+1)=="-" then
                local ep
                if src:match("^%-%-%[=*%[",pos) then ep=_hk_skstr(src,pos+2)
                else local e=src:find("\n",pos,true); ep=(e and e+1) or n+1 end
                out[#out+1]=src:sub(pos,ep-1); pos=ep; handled=true
            elseif c=='"' or c=="'" or (c=="[" and src:match("^%[=*%[",pos)) then
                local ep=_hk_skstr(src,pos); out[#out+1]=src:sub(pos,ep-1); pos=ep; handled=true
            elseif c=="l" then
                local sub3=src:sub(pos)
                local _s,me2,vn2=sub3:find("^local%s+([%a_][%w_]*)%s*=%s*function%s*")
                if _s then
                    local me_abs=pos+me2
                    local pi=me_abs
                    while pi<=n and src:sub(pi,pi):match("%s") do pi=pi+1 end
                    if src:sub(pi,pi)=="(" then
                        local pd,pj,pe2=0,pi
                        while pj<=n do
                            local pc=src:sub(pj,pj)
                            if pc=="(" then pd=pd+1
                            elseif pc==")" then pd=pd-1; if pd==0 then pe2=pj; break end end
                            pj=pj+1
                        end
                        if pe2 then
                            local args=src:sub(pi,pe2)
                            local fe=_hk_fend(src,pe2+1)
                            if fe then
                                local body=src:sub(pe2+1,fe-4)
                                local tx=("local %s;do local _i={f=function%s%send};%s=function(...)return _i.f(...)end;local _r=rawget(_G,'_hkR')or{};rawset(_G,'_hkR',_r);_r[%s]=_i end"):format(vn2,args,body,vn2,vn2)
                                out[#out+1]=tx; pos=fe; cnt=cnt+1; handled=true
                            end
                        end
                    end
                end
            end
            if not handled then out[#out+1]=c; pos=pos+1 end
        end
        return table.concat(out),cnt
    end
    local _hkt,_hkc=_hk_xform(prepared)
    if _hkc>0 then
        prepared=_hkt
        log(("hookfn-prepass: wrapped %d local function(s) as hookable"):format(_hkc))
    end
end

local function _normalize_luau_for_in(source)
    return (source:gsub("([^\n]*)\n", function(line)
        if line:match("^%s*%-%-") then return line .. "\n" end
        local lead, vars, expr = line:match("^(%s*for%s+)([%w_]+%s*,%s*[%w_]+)%s+in%s+([%w_%.]+)%s+do%s*$")
        if lead then return lead .. vars .. " in pairs(" .. expr .. ") do\n" end
        return line .. "\n"
    end))
end
prepared = _normalize_luau_for_in(prepared)

-- Bind a plain Vector3 value type lexically into user chunks. The host bridge
-- exposes Vector3 as a table but its constructor returns recursive userdata.
do
    local safe_v3 = {}
    local safe_v3_mt = {
        __type = "Vector3",
        __metatable = "Vector3",
        __index = function(obj, key)
            local x, y, z = rawget(obj, "X") or 0, rawget(obj, "Y") or 0, rawget(obj, "Z") or 0
            if key == "Magnitude" then return math.sqrt(x*x + y*y + z*z) end
            if key == "Unit" then
                local m = math.sqrt(x*x + y*y + z*z); if m == 0 then m = 1 end
                return safe_v3.new(x/m, y/m, z/m)
            end
            if key == "Dot" then return function(_, o) return x*(o.X or 0) + y*(o.Y or 0) + z*(o.Z or 0) end end
            if key == "Cross" then return function(_, o) return safe_v3.new(y*(o.Z or 0)-z*(o.Y or 0), z*(o.X or 0)-x*(o.Z or 0), x*(o.Y or 0)-y*(o.X or 0)) end end
            if key == "Lerp" then return function(_, o, alpha)
                return safe_v3.new(x + ((o.X or 0)-x)*alpha, y + ((o.Y or 0)-y)*alpha, z + ((o.Z or 0)-z)*alpha)
            end end
        end,
        __tostring = function(obj) return string.format("%g, %g, %g", rawget(obj, "X") or 0, rawget(obj, "Y") or 0, rawget(obj, "Z") or 0) end,
        __add = function(a,b) return safe_v3.new((a.X or 0)+(b.X or 0),(a.Y or 0)+(b.Y or 0),(a.Z or 0)+(b.Z or 0)) end,
        __sub = function(a,b) return safe_v3.new((a.X or 0)-(b.X or 0),(a.Y or 0)-(b.Y or 0),(a.Z or 0)-(b.Z or 0)) end,
        __unm = function(a) return safe_v3.new(-(a.X or 0),-(a.Y or 0),-(a.Z or 0)) end,
        __mul = function(a,b)
            if type(a) == "number" then return safe_v3.new(a*(b.X or 0),a*(b.Y or 0),a*(b.Z or 0)) end
            return safe_v3.new((a.X or 0)*(b or 0),(a.Y or 0)*(b or 0),(a.Z or 0)*(b or 0))
        end,
        __div = function(a,b) return safe_v3.new((a.X or 0)/(b or 1),(a.Y or 0)/(b or 1),(a.Z or 0)/(b or 1)) end,
        __eq = function(a,b) return a.X == b.X and a.Y == b.Y and a.Z == b.Z end,
    }
    safe_v3.new = function(x,y,z)
        return setmetatable({X=tonumber(x) or 0, Y=tonumber(y) or 0, Z=tonumber(z) or 0}, safe_v3_mt)
    end
    safe_v3.zero = safe_v3.new(0,0,0)
    safe_v3.one = safe_v3.new(1,1,1)
    local function _safe_f32(x)
        x = tonumber(x) or 0
        if x == 0 or x ~= x or x == math.huge or x == -math.huge then return x end
        local sign = 1
        if x < 0 then sign = -1; x = -x end
        local m, e = math.frexp(x)
        local s = m * 16777216
        local fl = math.floor(s)
        local diff = s - fl
        if diff > 0.5 or (diff == 0.5 and fl % 2 ~= 0) then fl = fl + 1 end
        return sign * math.ldexp(fl / 16777216, e)
    end
    local safe_c3 = {}
    local safe_c3_mt = {
        __type = "Color3",
        __metatable = "Color3",
        __index = function(obj, key)
            if key == "ToHSV" then return function(self2)
                local r,g,b = rawget(self2,"R") or 0, rawget(self2,"G") or 0, rawget(self2,"B") or 0
                local mx,mn = math.max(r,g,b),math.min(r,g,b); local d=mx-mn; local h=0
                if d > 0 then if mx==r then h=((g-b)/d)%6 elseif mx==g then h=(b-r)/d+2 else h=(r-g)/d+4 end; h=h/6 end
                return h, (mx > 0 and d/mx or 0), mx
            end end
            if key == "Lerp" then return function(self2, other, alpha)
                alpha = _safe_f32(alpha or 0)
                return safe_c3.new((self2.R or 0)+((other.R or 0)-(self2.R or 0))*alpha, (self2.G or 0)+((other.G or 0)-(self2.G or 0))*alpha, (self2.B or 0)+((other.B or 0)-(self2.B or 0))*alpha)
            end end
        end,
        __tostring = function(obj) return string.format("%g, %g, %g", rawget(obj,"R") or 0, rawget(obj,"G") or 0, rawget(obj,"B") or 0) end,
        __eq = function(a,b) return a.R==b.R and a.G==b.G and a.B==b.B end,
    }
    safe_c3.new = function(r,g,b)
        return setmetatable({
            R=_safe_f32(math.max(0,math.min(1,tonumber(r) or 0))),
            G=_safe_f32(math.max(0,math.min(1,tonumber(g) or 0))),
            B=_safe_f32(math.max(0,math.min(1,tonumber(b) or 0))),
        }, safe_c3_mt)
    end
    safe_c3.fromRGB = function(r,g,b) return safe_c3.new((r or 0)/255,(g or 0)/255,(b or 0)/255) end
    safe_c3.fromHSV = function(h,s,v)
        h,s,v = tonumber(h) or 0, tonumber(s) or 0, tonumber(v) or 0
        local i = math.floor(h * 6); local f = h * 6 - i
        local p = v * (1 - s); local q = v * (1 - f*s); local t = v * (1 - (1-f)*s)
        i = i % 6
        if i == 0 then return safe_c3.new(v,t,p)
        elseif i == 1 then return safe_c3.new(q,v,p)
        elseif i == 2 then return safe_c3.new(p,v,t)
        elseif i == 3 then return safe_c3.new(p,q,v)
        elseif i == 4 then return safe_c3.new(t,p,v)
        else return safe_c3.new(v,p,q) end
    end
    local safe_nsk = {}
    local safe_nsk_mt = {__type="NumberSequenceKeypoint", __metatable="NumberSequenceKeypoint"}
    safe_nsk.new = function(t,v,e)
        return setmetatable({Time=tonumber(t) or 0, Value=tonumber(v) or 0, Envelope=tonumber(e) or 0}, safe_nsk_mt)
    end
    local safe_csk = {}
    local safe_csk_mt = {__type="ColorSequenceKeypoint", __metatable="ColorSequenceKeypoint"}
    safe_csk.new = function(t,c)
        return setmetatable({Time=tonumber(t) or 0, Value=c or safe_c3.new(0,0,0)}, safe_csk_mt)
    end
    local safe_ns = {}
    local safe_ns_mt = {__type="NumberSequence", __metatable="NumberSequence"}
    safe_ns.new = function(value)
        local keys = {}
        if type(value) == "table" then
            for i, key in ipairs(value) do keys[i] = key end
        else
            local number = tonumber(value) or 0
            keys[1] = safe_nsk.new(0, number)
            keys[2] = safe_nsk.new(1, number)
        end
        return setmetatable({Keypoints=keys}, safe_ns_mt)
    end
    local safe_cs = {}
    local safe_cs_mt = {__type="ColorSequence", __metatable="ColorSequence"}
    safe_cs.new = function(value)
        local keys = {}
        if type(value) == "table" then
            for i, key in ipairs(value) do keys[i] = key end
        else
            keys[1] = safe_csk.new(0, value)
            keys[2] = safe_csk.new(1, value)
        end
        return setmetatable({Keypoints=keys}, safe_cs_mt)
    end
    rawset(_G, "__FLAME_SAFE_VECTOR3", safe_v3)
    rawset(_G, "__FLAME_SAFE_COLOR3", safe_c3)
    rawset(_G, "__FLAME_SAFE_NUMBER_SEQUENCE", safe_ns)
    rawset(_G, "__FLAME_SAFE_NUMBER_SEQUENCE_KEYPOINT", safe_nsk)
    rawset(_G, "__FLAME_SAFE_COLOR_SEQUENCE", safe_cs)
    rawset(_G, "__FLAME_SAFE_COLOR_SEQUENCE_KEYPOINT", safe_csk)
    if prepared:find("Vector3", 1, true) or prepared:find("Color3", 1, true) then
        local prefix = ""
        if prepared:find("Vector3", 1, true) then prefix = prefix .. "local Vector3 = __FLAME_SAFE_VECTOR3\n" end
        if prepared:find("Color3", 1, true) then prefix = prefix .. "local Color3 = __FLAME_SAFE_COLOR3\n" end
        if prepared:find("NumberSequence", 1, true) then
            prefix = prefix .. "local NumberSequence = __FLAME_SAFE_NUMBER_SEQUENCE\nlocal NumberSequenceKeypoint = __FLAME_SAFE_NUMBER_SEQUENCE_KEYPOINT\n"
        end
        if prepared:find("ColorSequence", 1, true) then
            prefix = prefix .. "local ColorSequence = __FLAME_SAFE_COLOR_SEQUENCE\nlocal ColorSequenceKeypoint = __FLAME_SAFE_COLOR_SEQUENCE_KEYPOINT\n"
        end
        prepared = prefix .. prepared
    end
end

local chunk, err = _real_load(prepared, "=script")
if not chunk and is_local_limit(err) then
    log("local-limit hit, promoting top-level locals to globals")
    local rewritten = strip_locals(prepared, "toplevel")
    local c2, e2 = _real_load(rewritten, "=script_top")
    if c2 then chunk, err, prepared = c2, nil, rewritten
    else chunk, err = nil, e2 end
end
if not chunk and is_local_limit(err) then
    log("local-limit still hit, promoting ALL locals to globals")
    local rewritten = strip_locals(prepared, "all")
    local c3, e3 = _real_load(rewritten, "=script_all")
    if c3 then chunk, err, prepared = c3, nil, rewritten
    else chunk, err = nil, e3 end
end
assert(chunk, "load error: " .. tostring(err))

do
    local _ccl_set  = setmetatable({}, { __mode = "k" })
    local _exec_set = setmetatable({}, { __mode = "k" })
    for _, lib in ipairs({string, table, math, os, coroutine, bit32, utf8, debug}) do
        if type(lib) == "table" then
            for _, v in pairs(lib) do
                if type(v) == "function" then _ccl_set[v] = true end
            end
        end
    end
    for _, fn in ipairs({print, warn, error, assert, pcall, xpcall, pairs, ipairs, next, type, typeof, tostring, tonumber, select, unpack, rawget, rawset, rawequal, rawlen, setmetatable, getmetatable, load, loadstring, newproxy, tick, wait, spawn, delay}) do
        if type(fn) == "function" then _ccl_set[fn] = true end
    end

    local _prev_newcclosure = newcclosure
    newcclosure = function(f)
        if type(f) ~= "function" then return f end
        local wrapper = function(...) return f(...) end
        _ccl_set[wrapper]  = true
        _exec_set[wrapper] = true
        return wrapper
    end

    local _prev_iscclosure = iscclosure
    iscclosure = function(f)
        if type(f) ~= "function" then return false end
        if _ccl_set[f] then return true end
        if type(debug) == "table" and type(debug.info) == "function" then
            local okInfo, src = pcall(debug.info, f, "s")
            if okInfo and src == "[C]" then
                _ccl_set[f] = true
                return true
            end
        end
        local sd = _G._origStringDump or (type(string) == "table" and rawget(string, "dump"))
        if type(sd) == "function" then
            local ok, res = pcall(sd, f)
            if ok then return false end
            local msg = type(res) == "string" and res or ""
            if not msg:find("not available", 1, true) and not msg:find("attempt to dump given function", 1, true) then
                return true
            end
        end
        return false
    end

    local _prev_islclosure = islclosure
    islclosure = function(f)
        if type(f) ~= "function" then return false end
        return not iscclosure(f)
    end

    isexecutorclosure = function(f)
        if type(f) ~= "function" then return false end
        if _exec_set[f] == true then return true end
        local ok_source, source = pcall(debug.info, f, "s")
        if ok_source and type(source) == "string" then
            return not (source == "=[C]" or source == "[C]" or source:sub(1, 3) == "=[C")
        end
        return islclosure(f)
    end
    is_synapse_function = is_synapse_function or isexecutorclosure

    local function _make_env_proxy(label)
        return setmetatable({}, {
            __index     = _G,
            __newindex  = function(_, k, v) rawset(_G, k, v) end,
            __metatable = "The metatable is locked",
            __tostring  = function() return label end,
        })
    end
    local _genv = _make_env_proxy("getgenv")
    local _renv = _make_env_proxy("getrenv")
    getgenv = function() return _genv end
    getrenv = function() return _renv end

    local _prev_getgc = getgc
    getgc = function(...)
        if type(_prev_getgc) == "function" then
            local ok, v = pcall(_prev_getgc, ...)
            if ok and type(v) == "table" then return v end
        end
        return {}
    end

    if not _G.__plain_tee_installed then
        _G.__plain_tee_installed = true
        _G.__plain_tee_buffer = {}
        local _buf = _G.__plain_tee_buffer
        local _real_print = print
        local _real_iow   = io and io.write
        local _real_warn  = warn

        local function _ql(v)
            local t = type(v)
            if t == "string"  then return string.format("%q", v)
            elseif t == "number" or t == "boolean" then return tostring(v)
            elseif v == nil   then return "nil"
            else return "" .. tostring(v) end
        end
        local function _qlargs(...)
            local n = select("#", ...)
            local parts = {}
            for i = 1, n do parts[i] = _ql(select(i, ...)) end
            return table.concat(parts, ", ")
        end

        print = function(...)
            _buf[#_buf + 1] = "print(" .. _qlargs(...) .. ")\n"
            return _real_print(...)
        end
        _ccl_set[print] = true

        if _real_iow then
            io.write = function(...)
                _buf[#_buf + 1] = "io.write(" .. _qlargs(...) .. ")"
                local s = ""
                for i = 1, select("#", ...) do
                    s = s .. tostring(select(i, ...))
                end
                return _real_iow(s)
            end
            _ccl_set[io.write] = true
        end

        if type(_real_warn) == "function" then
            warn = function(...)
                _buf[#_buf + 1] = "warn(" .. _qlargs(...) .. ")\n"
                return _real_warn(...)
            end
            _ccl_set[warn] = true
        end
    end
end

do
    if not _G.dumperState then
        local _GRAVITY = 196.2
        local _DEF_SX, _DEF_SY, _DEF_SZ = 4, 1, 2

        local _isyieldable = coroutine.isyieldable
                          or function() return coroutine.running() ~= nil end

        local _sa_parts = setmetatable({}, { __mode = "k" })
        local _sa_signals = setmetatable({}, { __mode = "k" })

        if type(_G.Vector3) ~= "table"
           or type(_G.Vector3.new) ~= "function" then
            local _v3_api = type(_G.Vector3) == "table" and _G.Vector3 or {}
            local _v3mt = {
                __metatable = "Vector3",
                __tostring  = function(s)
                    return ("%g, %g, %g"):format(s.X, s.Y, s.Z)
                end,
            }
            local function _v3(x, y, z)
                x = tonumber(x) or 0
                y = tonumber(y) or 0
                z = tonumber(z) or 0
                local mag = math.sqrt(x*x + y*y + z*z)
                local v = { X=x, Y=y, Z=z, Magnitude=mag }
                if mag > 1e-9 then
                    local ux, uy, uz = x/mag, y/mag, z/mag
                    local uv = { X=ux, Y=uy, Z=uz, Magnitude=1.0 }
                    uv.Unit = uv
                    uv.Dot   = function(self, b) return self.X*b.X + self.Y*b.Y + self.Z*b.Z end
                    uv.Cross = function(self, b)
                        return _v3(self.Y*b.Z-self.Z*b.Y, self.Z*b.X-self.X*b.Z, self.X*b.Y-self.Y*b.X)
                    end
                    uv.Lerp  = function(self, b, t) return _v3(self.X+(b.X-self.X)*t, self.Y+(b.Y-self.Y)*t, self.Z+(b.Z-self.Z)*t) end
                    setmetatable(uv, _v3mt)
                    v.Unit = uv
                else
                    v.Unit = v
                end
                v.Dot   = function(self, b) return self.X*b.X + self.Y*b.Y + self.Z*b.Z end
                v.Cross = function(self, b)
                    return _v3(self.Y*b.Z-self.Z*b.Y, self.Z*b.X-self.X*b.Z, self.X*b.Y-self.Y*b.X)
                end
                v.Lerp  = function(self, b, t) return _v3(self.X+(b.X-self.X)*t, self.Y+(b.Y-self.Y)*t, self.Z+(b.Z-self.Z)*t) end
                _v3mt.__add = function(a, b) return _v3(a.X+b.X, a.Y+b.Y, a.Z+b.Z) end
                _v3mt.__sub = function(a, b) return _v3(a.X-b.X, a.Y-b.Y, a.Z-b.Z) end
                _v3mt.__mul = function(a, b)
                    if type(a) == "number" then return _v3(a*b.X, a*b.Y, a*b.Z)
                    elseif type(b) == "number" then return _v3(a.X*b, a.Y*b, a.Z*b)
                    end; return _v3(a.X*b.X, a.Y*b.Y, a.Z*b.Z)
                end
                _v3mt.__div = function(a, b)
                    if type(b) == "number" then return _v3(a.X/b, a.Y/b, a.Z/b) end
                    return _v3(a.X/b.X, a.Y/b.Y, a.Z/b.Z)
                end
                _v3mt.__unm = function(a) return _v3(-a.X, -a.Y, -a.Z) end
                _v3mt.__eq  = function(a, b) return a.X==b.X and a.Y==b.Y and a.Z==b.Z end
                return setmetatable(v, _v3mt)
            end
            _v3_api.new   = _v3
            _v3_api.zero  = _v3(0, 0, 0)
            _v3_api.one   = _v3(1, 1, 1)
            _v3_api.xAxis = _v3(1, 0, 0)
            _v3_api.yAxis = _v3(0, 1, 0)
            _v3_api.zAxis = _v3(0, 0, 1)
            _G.Vector3 = _v3_api
        end

        if type(_G.CFrame) ~= "table"
           or type(_G.CFrame.new) ~= "function" then
            local function _cf(x, y, z)
                x = tonumber(x) or 0
                y = tonumber(y) or 0
                z = tonumber(z) or 0
                local cf = {
                    X = x, Y = y, Z = z,
                    Position    = _G.Vector3.new(x, y, z),
                    LookVector  = _G.Vector3.new(0,  0, -1),
                    UpVector    = _G.Vector3.new(0,  1,  0),
                    RightVector = _G.Vector3.new(1,  0,  0),
                }
                return setmetatable(cf, {
                    __metatable = "CFrame",
                    __tostring  = function(s)
                        return ("%g, %g, %g, 1, 0, 0, 0, 1, 0, 0, 0, 1")
                               :format(s.X, s.Y, s.Z)
                    end,
                })
            end
            _G.CFrame = {
                new      = _cf,
                identity = _cf(0, 0, 0),
            }
        end

        local _v3new = _G.Vector3.new
        local _cfnew = _G.CFrame.new

        local function _fire_changed(proxy, propName)
            local sigs = _sa_signals[proxy]
            if not sigs then return end
            local cbs = sigs[propName]
            if not cbs then return end
            for i = 1, #cbs do pcall(cbs[i]) end
        end

        local function _make_prop_signal(proxy, propName)
            if not _sa_signals[proxy] then
                _sa_signals[proxy] = {}
            end
            local sigs = _sa_signals[proxy]
            if not sigs[propName] then sigs[propName] = {} end
            local cbs = sigs[propName]
            local sig = {}
            sig.Connect = function(self, fn)
                if type(fn) == "function" then cbs[#cbs + 1] = fn end
                local conn = { Connected = true }
                conn.Disconnect = function()
                    conn.Connected = false
                    for i, f in ipairs(cbs) do
                        if f == fn then table.remove(cbs, i); break end
                    end
                end
                conn.disconnect = conn.Disconnect
                return conn
            end
            sig.Wait   = function(self) return nil end
            sig.Once   = function(self, fn)
                if type(fn) ~= "function" then return end
                local conn
                conn = self:Connect(function(...)
                    conn:Disconnect(); fn(...)
                end)
                return conn
            end
            return sig
        end

        local function _restingY(proxy, sx, sy, sz)
            local st = _sa_parts[proxy]
            if not st then return nil end
            local px, pz = st.x, st.z
            local best = nil
            for other, ost in pairs(_sa_parts) do
                if other ~= proxy and ost.anchored and ost.alive then
                    local dx = math.abs(px - ost.x)
                    local dz = math.abs(pz - ost.z)
                    if dx <= (sx + ost.sx) * 0.5
                    and dz <= (sz + ost.sz) * 0.5 then
                        local topY = ost.y + ost.sy * 0.5 + sy * 0.5
                        if best == nil or topY > best then
                            best = topY
                        end
                    end
                end
            end
            return best
        end

        local function _stepPhysics(dt)
            dt = tonumber(dt)
            if not dt or dt <= 0 then return end
            if dt > 30 then dt = 30 end
            for proxy, st in pairs(_sa_parts) do
                if not st.anchored and st.alive then
                    local sx, sy, sz = st.sx, st.sy, st.sz
                    local newY  = st.y + st.vy * dt
                                - 0.5 * _GRAVITY * dt * dt
                    local newVy = st.vy - _GRAVITY * dt
                    local restY = _restingY(proxy, sx, sy, sz)
                    if restY ~= nil and newY <= restY then
                        newY  = restY
                        newVy = 0
                    end
                    st.vy = newVy
                    st.y  = newY
                end
            end
        end

        local function _mkGenericInst(className)
            local props = { ClassName = className }
            local inst
            inst = setmetatable({}, {
                __metatable = "Instance",
                __index = function(_, k)
                    if k == "Destroy" then
                        return function(_self) props.Parent = nil end
                    end
                    if k == "IsA" then
                        return function(_self, cn)
                            return cn == className or cn == "Instance"
                        end
                    end
                    if k == "GetFullName" then
                        return function() return tostring(className) end
                    end
                    if k == "Clone" then
                        return function(_self) return _mkGenericInst(className) end
                    end
                    if k == "GetPropertyChangedSignal" then
                        return function(_self, prop)
                            return _make_prop_signal(inst, prop)
                        end
                    end
                    if k == "GetAttributeChangedSignal" then
                        return function(_self, attr)
                            return _make_prop_signal(inst, "__attr_"..tostring(attr))
                        end
                    end
                    if k == "FindFirstChild" or k == "FindFirstChildOfClass"
                    or k == "FindFirstAncestorOfClass" then
                        return function() return nil end
                    end
                    if k == "GetChildren" or k == "GetDescendants" then
                        return function() return {} end
                    end
                    if k == "WaitForChild" then
                        return function(_self, name) return nil end
                    end
                    if k == "IsDescendantOf" then
                        return function() return false end
                    end
                    if k == "GetAttribute" then return function() return nil end end
                    if k == "SetAttribute" then return function() end end
                    return props[k]
                end,
                __newindex = function(_, k, v)
                    props[k] = v
                    _fire_changed(inst, k)
                end,
                __tostring = function() return tostring(className) end,
            })
            return inst
        end

        local _SA_PART_CLASSES = {
            Part=true, MeshPart=true, WedgePart=true,
            TrussPart=true, CornerWedgePart=true,
            SpawnLocation=true, SeatPart=true, Seat=true,
            VehicleSeat=true, BasePart=true,
        }

        local function _mkSaPart(className)
            local st = {
                x=0, y=0, z=0,
                sx=_DEF_SX, sy=_DEF_SY, sz=_DEF_SZ,
                vy=0, anchored=false, alive=false,
            }
            local props = {
                ClassName    = className or "Part",
                CanCollide   = true,
                Transparency = 0,
                Name         = className or "Part",
            }
            local part
            part = setmetatable({}, {
                __metatable = "Instance",
                __index = function(_, k)
                    if k == "Position" then return _v3new(st.x, st.y, st.z) end
                    if k == "CFrame"   then return _cfnew(st.x, st.y, st.z) end
                    if k == "Size"     then return _v3new(st.sx, st.sy, st.sz) end
                    if k == "Anchored" then return st.anchored end
                    if k == "Destroy"  then
                        return function(_self)
                            st.alive = false; props.Parent = nil
                        end
                    end
                    if k == "GetPropertyChangedSignal" then
                        return function(_self, prop)
                            return _make_prop_signal(part, prop)
                        end
                    end
                    if k == "GetAttributeChangedSignal" then
                        return function(_self, attr)
                            return _make_prop_signal(part, "__attr_"..tostring(attr))
                        end
                    end
                    if k == "IsA" then
                        return function(_self, cn)
                            return cn=="BasePart" or cn=="Instance" or cn==className
                        end
                    end
                    if k == "GetFullName" then
                        return function()
                            return "Workspace."..tostring(className or "Part")
                        end
                    end
                    if k == "IsDescendantOf" then
                        return function() return st.alive end
                    end
                    if k == "Clone" then
                        return function(_self) return _mkSaPart(className) end
                    end
                    if k == "FindFirstChild" or k == "FindFirstChildOfClass" then
                        return function() return nil end
                    end
                    if k == "GetChildren" or k == "GetDescendants" then
                        return function() return {} end
                    end
                    return props[k]
                end,
                __newindex = function(_, k, v)
                    props[k] = v
                    if k == "Anchored" then
                        st.anchored = (v == true)
                    elseif k == "Position" and type(v) == "table" then
                        st.x  = tonumber(v.X) or 0
                        st.y  = tonumber(v.Y) or 0
                        st.z  = tonumber(v.Z) or 0
                        st.vy = 0
                    elseif k == "CFrame" and type(v) == "table" then
                        local px = tonumber(v.X)
                        local py = tonumber(v.Y)
                        local pz = tonumber(v.Z)
                        if px == nil and type(v.Position) == "table" then
                            px = tonumber(v.Position.X)
                            py = tonumber(v.Position.Y)
                            pz = tonumber(v.Position.Z)
                        end
                        if px then
                            st.x, st.y, st.z, st.vy = px, py or 0, pz or 0, 0
                        end
                    elseif k == "Size" and type(v) == "table" then
                        local sx = tonumber(v.X)
                        local sy = tonumber(v.Y)
                        local sz = tonumber(v.Z)
                        if sx and sx > 0 then st.sx = sx end
                        if sy and sy > 0 then st.sy = sy end
                        if sz and sz > 0 then st.sz = sz end
                    elseif k == "Parent" then
                        st.alive = (v ~= nil)
                    end
                    _fire_changed(part, k)
                end,
                __tostring = function(_)
                    return tostring(className or "Part")
                end,
            })
            _sa_parts[part] = st
            return part
        end

        if type(_G.Instance) ~= "table" then _G.Instance = {} end
        if not rawget(_G.Instance, "__saPhysInstalled") then
            _G.Instance.new = function(className, parent)
                local inst
                if _SA_PART_CLASSES[className] then
                    inst = _mkSaPart(className)
                else
                    inst = _mkGenericInst(className)
                end
                if parent ~= nil then inst.Parent = parent end
                return inst
            end
            rawset(_G.Instance, "__saPhysInstalled", true)
        end

        do
            local ws = type(_fake_services) == "table"
                   and rawget(_fake_services, "Workspace")
            if type(ws) == "table"
            and not rawget(ws, "__saWorkspacePatched") then
                rawset(ws, "__saWorkspacePatched", true)

                rawset(ws, "BulkMoveTo", function(self, parts_tbl, cframes_tbl, mode)
                    if type(parts_tbl) ~= "table"
                    or type(cframes_tbl) ~= "table" then return end
                    for i = 1, #parts_tbl do
                        local p  = parts_tbl[i]
                        local cf = cframes_tbl[i]
                        if p ~= nil and cf ~= nil then
                            p.CFrame = cf
                        end
                    end
                end)

                rawset(ws, "FindFirstChild",        function(_, name) return nil end)
                rawset(ws, "FindFirstChildOfClass", function(_, cn)   return nil end)
                rawset(ws, "GetChildren",           function(_) return {} end)
                rawset(ws, "GetDescendants",        function(_) return {} end)
                rawset(ws, "WaitForChild",          function(_, name) return nil end)
                rawset(ws, "IsAncestorOf",          function(_, inst) return false end)
                rawset(ws, "IsDescendantOf",        function(_, inst) return false end)

                local _empty_rc = { Instance = nil, Position = nil,
                                    Normal = nil, Material = nil, Distance = 0 }
                rawset(ws, "Raycast",         function() return nil end)
                rawset(ws, "FindPartOnRay",   function() return nil end)
                rawset(ws, "FindPartOnRayWithIgnoreList",
                                              function() return nil end)

                rawset(ws, "GetBoundingBox",  function()
                    return _cfnew(0,0,0), _v3new(0,0,0)
                end)
            end
        end

        local _hb_pending = {}

        local function _hb_add(co)
            _hb_pending[#_hb_pending + 1] = co
        end

        local function _hb_tick()
            local q = _hb_pending
            _hb_pending = {}
            for i = 1, #q do
                local co = q[i]
                if coroutine.status(co) ~= "dead" then
                    coroutine.resume(co)
                end
            end
        end

        local _hb_sa_cbs   = {}
        local _hb_sa_fired = 0
        local _HB_SA_DTS   = { 0.0167, 0.0183, 0.0159, 0.0176, 0.0162,
                                0.0171, 0.0155, 0.0168, 0.0178, 0.0160 }
        local function _hb_sa_fire_all()
            _hb_sa_fired = _hb_sa_fired + 1
            local dt = _HB_SA_DTS[(_hb_sa_fired - 1) % #_HB_SA_DTS + 1]
            for id, cb in pairs(_hb_sa_cbs) do
                if type(cb) == "function" then pcall(cb, dt) end
            end
            return dt
        end

        local _hb_signal = {}
        _hb_signal.Wait = function(self)
            if _isyieldable() then
                local co = coroutine.running()
                if co then _hb_add(co) end
                coroutine.yield()
            else
                _hb_tick()
            end
            return _HB_SA_DTS[(_hb_sa_fired) % #_HB_SA_DTS + 1]
        end
        _hb_signal.Connect = function(self, fn)
            if type(fn) ~= "function" then
                local conn = { Connected = true }
                conn.Disconnect = function() conn.Connected = false end
                conn.disconnect = conn.Disconnect
                return conn
            end
            local id = #_hb_sa_cbs + 1
            _hb_sa_cbs[id] = fn
            local conn = { Connected = true }
            local function _disc()
                _hb_sa_cbs[id] = nil
                conn.Connected = false
            end
            conn.Disconnect = _disc
            conn.disconnect = _disc
            for _ = 1, 10 do
                if _hb_sa_cbs[id] then
                    _hb_sa_fire_all()
                end
            end
            return conn
        end
        _hb_signal.Once = function(self, fn)
            if type(fn) ~= "function" then return self:Connect(fn) end
            local id = #_hb_sa_cbs + 1
            _hb_sa_cbs[id] = function(dt)
                _hb_sa_cbs[id] = nil
                pcall(fn, dt)
            end
            local conn = { Connected = true }
            conn.Disconnect = function() _hb_sa_cbs[id] = nil; conn.Connected = false end
            conn.disconnect = conn.Disconnect
            return conn
        end
        setmetatable(_hb_signal, {
            __index = function(_, k) return function() end end,
        })

        if type(_fake_services) == "table" then
            local rs = rawget(_fake_services, "RunService")
            if type(rs) == "table" then
                rawset(rs, "Heartbeat",     _hb_signal)
                rawset(rs, "RenderStepped", _hb_signal)
                rawset(rs, "Stepped",       _hb_signal)
            end
        end

        if not rawget(_G, "__saTaskSchedulerInstalled") then
            rawset(_G, "__saTaskSchedulerInstalled", true)

            local function _deferred_spawn(fn, ...)
                if type(fn) ~= "function" then return end
                local args = table.pack(...)
                local co = coroutine.create(function()
                    pcall(fn, table.unpack(args, 1, args.n))
                end)
                _hb_add(co)
                return co
            end

            local function _sa_wait(t)
                local _dt = _hb_sa_fire_all()
                if _isyieldable() then
                    local co = coroutine.running()
                    if co then _hb_add(co) end
                    coroutine.yield()
                else
                    _stepPhysics(t or 0.016)
                end
                return _dt
            end

            if type(_G.task) == "table" then
                _G.task.spawn = _deferred_spawn
                _G.task.defer = _deferred_spawn
                _G.task.delay = function(dt, fn, ...) return _deferred_spawn(fn, ...) end
                _G.task.wait  = _sa_wait
                rawset(_G.task, "__saPhysWaitInstalled", true)
            end
            _G.spawn = _deferred_spawn
            _G.wait  = _sa_wait
            rawset(_G, "__saPhysGlobalWaitInstalled", true)
        end
    end
end

do
    local _el = 0
    if prepared:find("getgenv",        1, true) then _el = _el + 1 end
    if prepared:find("getrenv",        1, true) then _el = _el + 1 end
