                    elseif type(b)=="number" then return _v2i16((a.X or 0)*b,(a.Y or 0)*b)
                    else return _v2i16((a.X or 0)*(b.X or 0),(a.Y or 0)*(b.Y or 0)) end
                end,
                __div = function(a,b)
                    if type(b)=="number" then return _v2i16((a.X or 0)/b,(a.Y or 0)/b)
