        local function _mkbc(name, num, r, g, b)
            local col = Color3 and Color3.new(r or 0, g or 0, b or 0) or {R=r or 0, G=g or 0, B=b or 0}
            local bc_mt = { __type="BrickColor", __metatable="BrickColor",
