    _G.EncodingService = setmetatable({}, {
        __metatable = "Instance",
        __index = function(_, k)
            if k=="ClassName"      then return "EncodingService" end
            if k=="ZstdCompress"   then return function(_,d) local s=tostring(d or ""); return "\0ZSTD\0"..s end end
            if k=="ZstdDecompress" then return function(_,d)
                local s=tostring(d or "")
                if s:sub(1,6)=="\0ZSTD\0" then return s:sub(7) end
                return s
            end end
            if k=="CompressBuffer" then return function(_, data)
                local text = (buffer and buffer.tostring and buffer.tostring(data)) or tostring(data or "")
                return buffer.fromstring("\0ZSTD\0" .. text)
            end end
            if k=="DecompressBuffer" then return function(_, data)
                local text = (buffer and buffer.tostring and buffer.tostring(data)) or tostring(data or "")
                if text:sub(1,6) == "\0ZSTD\0" then text = text:sub(7) end
                return buffer.fromstring(text)
