    do
        local ts = _G.TweenService or _fake_services["TweenService"]
        if ts ~= nil then
            local function _tween_signal(state)
                return setmetatable({}, {
                    __metatable = "The metatable is locked",
                    __index = function(_, key)
                        if key == "Connect" or key == "connect" then
                            return function(_, callback)
                                if type(callback) == "function" then
                                    state.callbacks[#state.callbacks + 1] = callback
                                end
                                return { Connected = true, Disconnect = function() end }
                            end
                        end
                        if key == "Once" then
                            return function(_, callback)
                                if type(callback) == "function" then
                                    state.callbacks[#state.callbacks + 1] = function(...)
                                        if not state.once_called then
                                            state.once_called = true
                                            callback(...)
                                        end
                                    end
                                end
                                return { Connected = true, Disconnect = function() end }
                            end
                        end
                        if key == "Wait" then
                            return function()
                                if not state.completed then
                                    local remaining = state.duration - (_sim_clock - state.started)
                                    if remaining > 0 then
                                        _sim_clock = _sim_clock + remaining
                                    end
                                    _advance_active_tweens()
                                end
                                return Enum and Enum.PlaybackState and Enum.PlaybackState.Completed
                            end
                        end
                    end,
                })
            end

            rawset(ts, "Create", function(self, inst, tweenInfo, propertyTable)
                if type(propertyTable) == "table" then
                    for key, value in pairs(propertyTable) do
                        local valueType = type(value)
                        if valueType ~= "number" and valueType ~= "boolean" then
                            local valueKind = typeof and typeof(value) or valueType
                            local allowed = {
                                Color3=true, Vector3=true, Vector2=true,
                                CFrame=true, UDim2=true, UDim=true,
                                number=true, boolean=true,
                            }
                            if not allowed[valueKind] and not allowed[valueType] then
                                error("unable to cast value to number", 2)
                            end
                        end
                    end
                end

                local state = {
                    instance = inst,
                    duration = 0,
                    goals = propertyTable or {},
                    starts = {},
                    started = _sim_clock,
                    playing = false,
                    completed = false,
                    callbacks = {},
                    once_called = false,
                }
                if tweenInfo ~= nil then
                    local ok, duration = pcall(function() return tweenInfo.Time end)
                    if ok then state.duration = tonumber(duration) or 0 end
                end
                if type(inst) == "table" and type(propertyTable) == "table" then
                    for key in pairs(propertyTable) do
                        local ok, value = pcall(function() return inst[key] end)
                        state.starts[key] = ok and value or nil
                    end
                end

                local tween
                tween = setmetatable({}, {
                    __metatable = "Instance",
                    __index = function(_, key)
                        if key == "ClassName" then return "Tween" end
                        if key == "Play" then
                            return function()
                                if not state.completed then
                                    state.started = _sim_clock
                                    state.playing = true
                                    _advance_active_tweens()
                                end
                            end
                        end
                        if key == "Destroy" then
                            return function()
                                state.playing = false
                                state.completed = true
                                state.callbacks = {}
                                _active_tweens[tween] = nil
                            end
                        end
                        if key == "Cancel" then
                            return function()
                                state.playing = false
                                state.completed = true
                            end
                        end
                        if key == "Pause" then
                            return function()
                                _advance_active_tweens()
                                state.playing = false
                            end
                        end
                        if key == "Completed" then return state.signal end
                        if key == "TweenInfo" then return tweenInfo end
                        if key == "PlaybackState" then
                            if state.completed then
                                return Enum and Enum.PlaybackState and Enum.PlaybackState.Completed
                            end
                            if state.playing then
                                return Enum and Enum.PlaybackState and Enum.PlaybackState.Playing
                            end
                            return Enum and Enum.PlaybackState and Enum.PlaybackState.Begin
                        end
                    end,
                    __newindex = rawset,
                })
                state.signal = _tween_signal(state)
                _active_tweens[tween] = state
                return tween
            end)
        end
    end

    do
        local function _st_check_val(v)
            local vt = type(v)
            if vt == "nil" or vt == "boolean" or vt == "number" or vt == "string" then return end
            if vt == "table" then
                local ok2, mt2 = pcall(getmetatable, v)
                if ok2 and mt2 == "SharedTable" then return end
            end
            error("invalid value to serialize: "..tostring(vt), 3)
        end
        if type(_G.SharedTable) == "table" and SharedTable.new then
            SharedTable.new = function(init)
                local st = {}
                if type(init) == "table" then
                    for k, v in pairs(init) do st[k] = v end
                end
                return setmetatable(st, {
                    __type = "SharedTable",
                    __metatable = "SharedTable",
                    __newindex = function(self, k, v)
                        local kt = type(k)
                        if kt ~= "string" and kt ~= "number" then
                            error("SharedTable key must be a string or number", 2)
                        end
                        _st_check_val(v)
                        rawset(self, k, v)
                    end,
                    __tostring = function() return "SharedTable" end,
                })
            end
        end
    end

