                end
                rawset(_G, "compareinstances", final_env.compareinstances)
                final_env.__FLAME_SAFE_VECTOR3 = Vector3
                rawset(_G, "__FLAME_SAFE_VECTOR3", Vector3)
                final_env.__FLAME_SAFE_COLOR3 = Color3 or rawget(_G, "__FLAME_SAFE_COLOR3")
                rawset(_G, "__FLAME_SAFE_COLOR3", final_env.__FLAME_SAFE_COLOR3)
                final_env.__FLAME_SAFE_NUMBER_SEQUENCE = NumberSequence or rawget(_G, "__FLAME_SAFE_NUMBER_SEQUENCE")
                final_env.__FLAME_SAFE_NUMBER_SEQUENCE_KEYPOINT = NumberSequenceKeypoint or rawget(_G, "__FLAME_SAFE_NUMBER_SEQUENCE_KEYPOINT")
                final_env.__FLAME_SAFE_COLOR_SEQUENCE = ColorSequence or rawget(_G, "__FLAME_SAFE_COLOR_SEQUENCE")
                final_env.__FLAME_SAFE_COLOR_SEQUENCE_KEYPOINT = ColorSequenceKeypoint or rawget(_G, "__FLAME_SAFE_COLOR_SEQUENCE_KEYPOINT")
                final_env._VERSION = "Luau"
            end
            local reloaded, reload_error = _real_load(prepared, "=script_main", "t", final_env)
            if reloaded then
                chunk = reloaded
            else
            end
        end
        local deferred = {}
        if type(task) == "table" then
            task.defer = function(fn, ...)
                deferred[#deferred + 1] = {fn, ...}
                return coroutine.create(function() end)
            end
            task.wait = function(duration)
                local dt = tonumber(duration) or (1 / 60)
                if dt < 0 then dt = 0 end
                _G.__flame_sim_time = (tonumber(_G.__flame_sim_time) or 0) + dt
                heartbeat:Fire(dt)
                local queue = deferred
                deferred = {}
                for _, item in ipairs(queue) do
                    if type(item[1]) == "function" then pcall(item[1], table.unpack(item, 2)) end
                end
                return dt
            end
        end
        if type(table) == "table" then
            table.clone = function(value)
                if type(value) ~= "table" then return value end
                local result = {}
                for key, item in pairs(value) do result[key] = item end
                return result
            end
        end
        if type(_G.TweenService) == "table" and type(_G.TweenService.Create) == "function" then
            local old_create = _G.TweenService.Create
            _G.TweenService.Create = function(self, object, info, goals)
                local tween = old_create(self, object, info, goals)
                if type(tween) == "table" and rawget(tween, "Destroy") == nil then
                    rawset(tween, "Destroy", function() end)
                end
                return tween
            end
        end
    end
end

-- Final runtime compatibility for readonly tables and Players lookups.
do
    local readonly_states = setmetatable({}, {__mode = "k"})
    local function readonly_set(target, enabled)
        if type(target) ~= "table" then
            error("setreadonly expects a table", 2)
        end
        local state = readonly_states[target]
        if enabled then
            if state and state.readonly then return target end
            local original_mt = getmetatable(target)
            if type(original_mt) == "string" then original_mt = nil end
            local shadow = {}
            for key, value in pairs(target) do
                shadow[key] = value
                rawset(target, key, nil)
            end
            local readonly_mt = {}
            if type(original_mt) == "table" then
                for key, value in pairs(original_mt) do
                    if key ~= "__index" and key ~= "__newindex" then
                        readonly_mt[key] = value
                    end
                end
            end
            local original_index = type(original_mt) == "table" and original_mt.__index or nil
            readonly_mt.__index = function(self, key)
                local value = shadow[key]
                if value ~= nil then return value end
                if type(original_index) == "function" then
                    return original_index(self, key)
                end
                if type(original_index) == "table" then return original_index[key] end
                return nil
            end
            readonly_mt.__newindex = function()
                error("attempt to modify a readonly table", 2)
            end
            state = {readonly = true, shadow = shadow, original_mt = original_mt}
            readonly_states[target] = state
            setmetatable(target, readonly_mt)
            return target
        end
        if state and state.readonly then
            for key, value in pairs(state.shadow) do rawset(target, key, value) end
            setmetatable(target, state.original_mt)
            state.readonly = false
            state.shadow = nil
        end
        return target
    end
    rawset(_G, "setreadonly", readonly_set)
    rawset(_G, "isreadonly", function(target)
        return type(target) == "table" and readonly_states[target] ~= nil and readonly_states[target].readonly == true
    end)

    local players_service = _fake_services.Players
    if players_service ~= nil then
        local local_player = rawget(players_service, "LocalPlayer")
        rawset(players_service, "NumPlayers", 1)
        rawset(players_service, "GetPlayers", function()
            return local_player and {local_player} or {}
        end)
        rawset(players_service, "GetPlayerByUserId", function(_, user_id)
            if local_player and tonumber(rawget(local_player, "UserId")) == tonumber(user_id) then
                return local_player
            end
            return nil
        end)
        rawset(players_service, "GetPlayerFromCharacter", function(_, character)
            if local_player and rawget(local_player, "Character") == character then
                return local_player
            end
            return nil
        end)
    end

    local function patch_service(name, entries)
        local service = _fake_services[name]
        if service ~= nil then
            for key, value in pairs(entries) do pcall(rawset, service, key, value) end
        end
    end
    patch_service("Stats", {
        InstanceCount = 100,
        GetTotalMemoryUsageMb = function() return 128 end,
        GetMemoryUsageMbForTag = function() return 16 end,
    })
    patch_service("Lighting", {
        GetMinutesAfterMidnight = function(self) return (tonumber(rawget(self, "ClockTime")) or 14) * 60 end,
        SetMinutesAfterMidnight = function(self, minutes) rawset(self, "ClockTime", (tonumber(minutes) or 0) / 60) end,
    })
    patch_service("PhysicsService", {
        GetRegisteredCollisionGroups = function() return {{name = "Default", mask = 0}} end,
        CollisionGroupsAreCollidable = function() return true end,
    })
    patch_service("SoundService", {
        DistanceFactor = 1,
        GetMixerTime = function() return os.clock() end,
    })
    patch_service("GuiService", {
        GetScreenResolution = function() return Vector2 and Vector2.new(1920, 1080) or {X=1920, Y=1080} end,
    })
    patch_service("MemStorageService", {
        SetItem = function(self, key, value) self._mem = self._mem or {}; self._mem[tostring(key)] = tostring(value); return true end,
        GetItem = function(self, key) return self._mem and self._mem[tostring(key)] or nil end,
    })
    patch_service("ContentProvider", {
        GetAssetFetchStatus = function() return Enum and Enum.AssetFetchStatus and Enum.AssetFetchStatus.None or nil end,
    })
    patch_service("AnimationClipProvider", {
        GetMemStats = function() return {DecodedAnimations = 1, CachedAnimations = 1} end,
    })
    patch_service("ReflectionService", {
        GetClasses = function() return {} end,
    })
    patch_service("VoiceChatService", {
        getInternalSessionId = function() return nil end,
        getInternalChannelId = function() return nil end,
        getInternalGroupId = function() return nil end,
        isInternalPublishPaused = function() return false end,
        lastVoiceChatStats = function() return nil end,
    })
    patch_service("AssetService", {
        CreateEditableMesh = function()
            local vertices = {}
            local mesh = {}
            function mesh:AddVertex(position) vertices[#vertices + 1] = position; return #vertices end
            function mesh:GetVertices() local out = {}; for i = 1, #vertices do out[i] = i end; return out end
            function mesh:GetPosition(index) return vertices[index] end
            function mesh:Destroy() end
            return mesh
        end,
    })
    local ws = _fake_services.Workspace
    if ws ~= nil then
        pcall(rawset, ws, "GetServerTimeNow", function() return os.time() end)
        pcall(rawset, ws, "GetNumAwakeParts", function() return 1 end)
        pcall(rawset, ws, "Raycast", function() return nil end)
    end
    pcall(rawset, game_proxy, "GetJobsInfo", function() return {{name = "Heartbeat"}} end)
end

-- Add CFrame.Lerp without altering the existing CFrame representation
do
    local _flame_cframe_api = rawget(_G, "CFrame")
    local _flame_old_cframe_new = type(_flame_cframe_api) == "table" and rawget(_flame_cframe_api, "new")
    if type(_flame_old_cframe_new) == "function" and rawget(_G, "__flame_cframe_lerp_patch") ~= true then
        rawset(_G, "__flame_cframe_lerp_patch", true)
        rawset(_flame_cframe_api, "new", function(...)
            local _flame_value = _flame_old_cframe_new(...)
            if type(_flame_value) == "table" then
                pcall(rawset, _flame_value, "Lerp", function(self, other, alpha)
                    local _flame_t = tonumber(alpha) or 0
                    if _flame_t < 0 then _flame_t = 0 elseif _flame_t > 1 then _flame_t = 1 end
                    local _flame_ox = tonumber(other and other.X) or 0
                    local _flame_oy = tonumber(other and other.Y) or 0
                    local _flame_oz = tonumber(other and other.Z) or 0
                    return _flame_old_cframe_new(
                        (tonumber(self.X) or 0) + (_flame_ox - (tonumber(self.X) or 0)) * _flame_t,
                        (tonumber(self.Y) or 0) + (_flame_oy - (tonumber(self.Y) or 0)) * _flame_t,
                        (tonumber(self.Z) or 0) + (_flame_oz - (tonumber(self.Z) or 0)) * _flame_t
                    )
                end)
            end
            return _flame_value
        end)
    end
end

-- Support ValueBase IsA checks and ancestor lookup on Instance stubs
do
    local _flame_instance_api = rawget(_G, "Instance")
    local _flame_old_instance_new = type(_flame_instance_api) == "table" and rawget(_flame_instance_api, "new")
    if type(_flame_old_instance_new) == "function" and rawget(_G, "__flame_valuebase_patch") ~= true then
        rawset(_G, "__flame_valuebase_patch", true)
        rawset(_flame_instance_api, "new", function(_flame_class_name, ...)
            local _flame_object = _flame_old_instance_new(_flame_class_name, ...)
            local _flame_class = tostring(_flame_class_name or "")
            if _flame_object ~= nil then
                local _flame_original_find_ancestor
                pcall(function() _flame_original_find_ancestor = _flame_object.FindFirstAncestor end)
                pcall(rawset, _flame_object, "FindFirstAncestor", function(self, wanted_name)
                    local _flame_target_name = tostring(wanted_name or "")
                    local _flame_current = self.Parent
                    local _flame_seen = {}
                    while _flame_current ~= nil and not _flame_seen[_flame_current] do
                        _flame_seen[_flame_current] = true
                        if tostring(_flame_current.Name or "") == _flame_target_name then
                            return _flame_current
                        end
                        _flame_current = _flame_current.Parent
                    end
                    if type(_flame_original_find_ancestor) == "function" then
                        return _flame_original_find_ancestor(self, wanted_name)
                    end
                    return nil
                end)
            end
            if _flame_object ~= nil and (_flame_class == "IntValue" or _flame_class == "NumberValue" or
                _flame_class == "BoolValue" or _flame_class == "StringValue" or
                _flame_class == "ObjectValue" or _flame_class == "CFrameValue" or
                _flame_class == "Vector3Value" or _flame_class == "Color3Value" or
                _flame_class == "BrickColorValue" or _flame_class == "RayValue") then
                local _flame_original_is_a
                pcall(function() _flame_original_is_a = _flame_object.IsA end)
                if type(_flame_original_is_a) == "function" then
                    pcall(rawset, _flame_object, "IsA", function(self, wanted)
                        wanted = tostring(wanted or "")
                        if wanted == "ValueBase" or wanted == "Instance" or wanted == _flame_class then
                            return true
                        end
                        return _flame_original_is_a(self, wanted)
                    end)
                end
            end
            return _flame_object
        end)
    end
end

-- Propagate CFrame:Lerp into payload environments
do
    local function _flame_wrap_payload_cframe(_flame_env)
        if type(_flame_env) ~= "table" then return end
        local _flame_api
        pcall(function() _flame_api = _flame_env.CFrame end)
        local _flame_constructor
        pcall(function() _flame_constructor = _flame_api.new end)
        if type(_flame_api) ~= "table" or type(_flame_constructor) ~= "function" then return end
        if rawget(_flame_api, "__flame_payload_lerp_patch") == true then return end
        rawset(_flame_api, "__flame_payload_lerp_patch", true)
        rawset(_flame_api, "new", function(...)
            local _flame_value = _flame_constructor(...)
            if type(_flame_value) == "table" then
                rawset(_flame_value, "Lerp", function(self, other, alpha)
                    local _flame_t = tonumber(alpha) or 0
                    if _flame_t < 0 then _flame_t = 0 elseif _flame_t > 1 then _flame_t = 1 end
                    local _flame_x = tonumber(self.X) or 0
                    local _flame_y = tonumber(self.Y) or 0
                    local _flame_z = tonumber(self.Z) or 0
                    local _flame_ox = tonumber(other and other.X) or 0
                    local _flame_oy = tonumber(other and other.Y) or 0
                    local _flame_oz = tonumber(other and other.Z) or 0
                    return _flame_constructor(
                        _flame_x + (_flame_ox - _flame_x) * _flame_t,
                        _flame_y + (_flame_oy - _flame_y) * _flame_t,
                        _flame_z + (_flame_oz - _flame_z) * _flame_t
                    )
                end)
            end
            return _flame_value
        end)
        local _flame_sample
        local _flame_sample_mt
        pcall(function()
            _flame_sample = _flame_constructor(0, 0, 0)
            _flame_sample_mt = getmetatable(_flame_sample)
        end)
        if type(_flame_sample_mt) == "table" and rawget(_flame_sample_mt, "__flame_lerp_patch") ~= true then
            local _flame_old_index = rawget(_flame_sample_mt, "__index")
            rawset(_flame_sample_mt, "__flame_lerp_patch", true)
            rawset(_flame_sample_mt, "__index", function(self, key)
                if key == "Lerp" then
                    return function(_, other, alpha)
                        local _flame_t = tonumber(alpha) or 0
                        if _flame_t < 0 then _flame_t = 0 elseif _flame_t > 1 then _flame_t = 1 end
                        local _flame_x = tonumber(self.X) or 0
                        local _flame_y = tonumber(self.Y) or 0
                        local _flame_z = tonumber(self.Z) or 0
                        local _flame_ox = tonumber(other and other.X) or 0
                        local _flame_oy = tonumber(other and other.Y) or 0
                        local _flame_oz = tonumber(other and other.Z) or 0
                        return _flame_constructor(
                            _flame_x + (_flame_ox - _flame_x) * _flame_t,
                            _flame_y + (_flame_oy - _flame_y) * _flame_t,
                            _flame_z + (_flame_oz - _flame_z) * _flame_t
                        )
                    end
                end
                if type(_flame_old_index) == "function" then return _flame_old_index(self, key) end
                if type(_flame_old_index) == "table" then return _flame_old_index[key] end
                return nil
            end)
        end
    end
    _flame_wrap_payload_cframe(CFrame)
    pcall(function() _flame_wrap_payload_cframe(_G.CFrame) end)
    local _flame_ds = rawget(_G, "dumperState")
    if type(_flame_ds) == "table" then
        _flame_wrap_payload_cframe(rawget(_flame_ds, "env"))
        _flame_wrap_payload_cframe(rawget(_flame_ds, "dsEnv"))
    end
    local _flame_chunk_env
    pcall(function() _flame_chunk_env = getfenv(chunk) end)
    _flame_wrap_payload_cframe(_flame_chunk_env)
    if _native_debug and type(_native_debug.getupvalue) == "function" then
        local _flame_up_ok, _flame_up_name, _flame_up_env = pcall(_native_debug.getupvalue, chunk, 1)
        if _flame_up_ok and _flame_up_name == "_ENV" and type(_flame_up_env) == "table" then
            _flame_wrap_payload_cframe(_flame_up_env)
            local _flame_direct_cframe
            pcall(function() _flame_direct_cframe = _flame_up_env.CFrame end)
            if type(_flame_direct_cframe) == "table" then
                pcall(rawset, _flame_up_env, "CFrame", _flame_direct_cframe)
            end
        end
    end
end

-- CollectionService per-tag signal backing
do
    local _flame_collection_service
    pcall(function() _flame_collection_service = game:GetService("CollectionService") end)
    if type(_flame_collection_service) == "table" then
        local _flame_added_signals = {}
        local _flame_removed_signals = {}
        local function _flame_tag_signal(cache, tag_name)
            local _flame_key = tostring(tag_name or "")
            if cache[_flame_key] == nil then
                local _flame_event = Instance.new("BindableEvent")
                cache[_flame_key] = _flame_event
            end
            return cache[_flame_key].Event
        end
        pcall(rawset, _flame_collection_service, "GetInstanceAddedSignal", function(_, tag_name)
            return _flame_tag_signal(_flame_added_signals, tag_name)
        end)
        pcall(rawset, _flame_collection_service, "GetInstanceRemovedSignal", function(_, tag_name)
            return _flame_tag_signal(_flame_removed_signals, tag_name)
        end)
    end
end

-- Spatial bounding-box queries for sandboxed parts
do
    local _flame_spatial_parts = {}
    local _flame_instance_api = Instance
    local _flame_spatial_old_new
    pcall(function() _flame_spatial_old_new = _flame_instance_api.new end)
    if type(_flame_instance_api) == "table" and type(_flame_spatial_old_new) == "function" then
        rawset(_flame_instance_api, "new", function(_flame_class_name, ...)
            local _flame_object = _flame_spatial_old_new(_flame_class_name, ...)
            local _flame_kind = tostring(_flame_class_name or "")
            if _flame_kind == "Part" or _flame_kind == "MeshPart" or _flame_kind == "UnionOperation" or
                _flame_kind == "WedgePart" or _flame_kind == "CornerWedgePart" or _flame_kind == "TrussPart" then
                _flame_spatial_parts[#_flame_spatial_parts + 1] = _flame_object
            end
            return _flame_object
        end)
    end
    local function _flame_spatial_contains(_flame_list, _flame_target)
        if type(_flame_list) ~= "table" then return false end
        for _, _flame_item in ipairs(_flame_list) do
            if _flame_item == _flame_target then return true end
        end
        return false
    end
    local function _flame_spatial_component(_flame_value, _flame_key, _flame_default)
        local _flame_ok, _flame_result = pcall(function() return _flame_value and _flame_value[_flame_key] end)
        if _flame_ok and type(_flame_result) == "number" then return _flame_result end
        return _flame_default or 0
    end
    local function _flame_install_spatial_query(_flame_workspace)
        if _flame_workspace == nil then return end
        pcall(rawset, _flame_workspace, "GetPartBoundsInBox", function(_, _flame_cf, _flame_size, _flame_params)
            local _flame_center = _flame_cf and _flame_cf.Position or _flame_cf
            local _flame_half = _flame_size
            local _flame_results = {}
            local _flame_include = _flame_params and _flame_params.IncludeInstances
            local _flame_exclude = _flame_params and _flame_params.ExcludeInstances
            if type(_flame_include) == "table" and #_flame_include == 0 then return _flame_results end
            for _, _flame_part in ipairs(_flame_spatial_parts) do
                local _flame_parent = nil
                local _flame_destroyed = false
                pcall(function()
                    _flame_parent = _flame_part.Parent
                    _flame_destroyed = _flame_part.__destroyed == true
                end)
                if _flame_parent == _flame_workspace and not _flame_destroyed then
                    local _flame_allowed = true
                    if _flame_include ~= nil and not _flame_spatial_contains(_flame_include, _flame_part) then
                        _flame_allowed = false
                    end
                    if _flame_exclude ~= nil and _flame_spatial_contains(_flame_exclude, _flame_part) then
                        _flame_allowed = false
                    end
                    if _flame_allowed then
                        local _flame_position = _flame_part.Position
                        if _flame_position == nil and _flame_part.CFrame then _flame_position = _flame_part.CFrame.Position end
                        local _flame_px = _flame_spatial_component(_flame_position, "X", 0)
                        local _flame_py = _flame_spatial_component(_flame_position, "Y", 0)
                        local _flame_pz = _flame_spatial_component(_flame_position, "Z", 0)
                        local _flame_cx = _flame_spatial_component(_flame_center, "X", 0)
                        local _flame_cy = _flame_spatial_component(_flame_center, "Y", 0)
                        local _flame_cz = _flame_spatial_component(_flame_center, "Z", 0)
                        local _flame_sx = _flame_spatial_component(_flame_size, "X", 4) / 2
                        local _flame_sy = _flame_spatial_component(_flame_size, "Y", 4) / 2
                        local _flame_sz = _flame_spatial_component(_flame_size, "Z", 4) / 2
                        local _flame_part_size = _flame_part.Size
                        local _flame_hx = _flame_spatial_component(_flame_part_size, "X", 4) / 2
                        local _flame_hy = _flame_spatial_component(_flame_part_size, "Y", 4) / 2
                        local _flame_hz = _flame_spatial_component(_flame_part_size, "Z", 4) / 2
                        if math.abs(_flame_px - _flame_cx) <= _flame_sx + _flame_hx and
                            math.abs(_flame_py - _flame_cy) <= _flame_sy + _flame_hy and
                            math.abs(_flame_pz - _flame_cz) <= _flame_sz + _flame_hz then
                            _flame_results[#_flame_results + 1] = _flame_part
                        end
                    end
                end
            end
            return _flame_results
        end)
    end
    pcall(function() _flame_install_spatial_query(workspace) end)
    pcall(function() _flame_install_spatial_query(game:GetService("Workspace")) end)
end

-- Shared helpers for sandboxed environment APIs
do
    local _flame_base_type = type
    local _flame_base_typeof = typeof
    local _flame_base_setmetatable = setmetatable
    local _flame_base_getmetatable = getmetatable
    local _flame_raw_metas = setmetatable({}, {__mode = "k"})
    local _flame_cclosures = setmetatable({}, {__mode = "k"})
    local _flame_instances = {}
    local _flame_instance_count = 0

    local _flame_chunk_env
    if _native_debug and type(_native_debug.getupvalue) == "function" then
        pcall(function()
            local ok_env, name, env = _native_debug.getupvalue(chunk, 1)
            if ok_env and name == "_ENV" then _flame_chunk_env = env end
        end)
    end
    local _flame_ds = rawget(_G, "dumperState")
    local _flame_envs = {}
    local _flame_seen_envs = setmetatable({}, {__mode = "k"})
    local function _flame_add_env(env)
        if type(env) == "table" and not _flame_seen_envs[env] then
            _flame_seen_envs[env] = true
            _flame_envs[#_flame_envs + 1] = env
        end
    end
    _flame_add_env(_flame_chunk_env)
    if type(_flame_ds) == "table" then
        _flame_add_env(_flame_ds.env)
        _flame_add_env(_flame_ds.dsEnv)
    end

    local _flame_function_type = function(value)
        local ok_value, value_type = pcall(_flame_base_typeof, value)
        if ok_value and value_type == "Instance" then return "userdata" end
        return _flame_base_type(value)
    end
    local _flame_genv = {}
    for key, value in pairs(_G) do _flame_genv[key] = value end
    local function _flame_getfenv(fn)
        if fn == nil then return _flame_chunk_env or _G end
        return _flame_chunk_env or _G
    end
    local _orig_sdump = rawget(_G, "_origStringDump") or (type(string) == "table" and rawget(string, "dump"))
    local function _flame_setfenv(fn, env)
        if _flame_base_type(fn) == "function" then
            if _flame_cclosures[fn] then
                error("'setfenv' cannot change environment of given object", 2)
            end
            if type(_orig_sdump) == "function" then
                local ok_dump = pcall(_orig_sdump, fn)
                if not ok_dump then error("'setfenv' cannot change environment of given object", 2) end
            end
        end
        return fn
    end
    local function _flame_debug_info(fn)
        if fn == _flame_genv or fn == _G.getgenv or _flame_cclosures[fn] then return {what = "C", source = "=[C]"} end
        return {what = "Lua", source = "=[C]"}
    end
    local _flame_debug_table = {}
    if type(_native_debug) == "table" then
        for key, value in pairs(_native_debug) do _flame_debug_table[key] = value end
    end
    _flame_debug_table.getinfo = _flame_debug_info
    _flame_debug_table.traceback = function(a, b) local m = type(a) == "thread" and b or a; return (m ~= nil and (tostring(m) .. "\n") or "") .. "stack traceback:\n\t[C]: in ?" end
    _flame_debug_table.getupvalue = function() return nil end

    local function _flame_is_cclosure(fn)
        if _flame_base_type(fn) ~= "function" then return false end
        if _flame_cclosures[fn] == true then return true end
        if type(_orig_sdump) == "function" then
            local ok_d = pcall(_orig_sdump, fn)
            return not ok_d
        end
        return false
    end

    local function _flame_install_env_api(env)
        if type(env) ~= "table" then return end
        env.type = _flame_function_type
        env.getfenv = _flame_getfenv
        env.setfenv = _flame_setfenv
        env.getgenv = function() return _flame_genv end
        env.getsenv = function(scriptObj)
            local isInst = (scriptObj == env.script) or (_flame_base_type(scriptObj) == "table" and (_flame_base_getmetatable(scriptObj) == "Instance" or rawget(scriptObj, "ClassName") ~= nil))
            if not isInst then
                error("invalid argument #1 to 'getsenv' (Instance expected, got " .. _flame_function_type(scriptObj) .. ")", 2)
            end
            if scriptObj ~= env.script then
                local cn = rawget(scriptObj, "ClassName") or ""
                if cn ~= "ModuleScript" and cn ~= "LocalScript" and cn ~= "Script" then
                    error("invalid argument #1 to 'getsenv' (ModuleScript/LocalScript/Script expected, got Instance)", 2)
                end
            end
            return env
        end
        env.gethiddenproperty = function(object, property)
            local key = tostring(property or "")
            if key == "SignalBehavior" then return Enum.SignalBehavior and (Enum.SignalBehavior.Deferred or Enum.SignalBehavior.Immediate) or nil end
            if key == "NetworkOwnerV3" then return true, true end
            if key == "Name" then
                local ok_name, name = pcall(function() return object.Name end)
                return ok_name and name or nil, false
            end
            local ok_value, value = pcall(function() return object[property] end)
            return ok_value and value or nil, false
        end
        env.isscriptable = function(object, property)
            local key = tostring(property or "")
            if key == "SignalBehavior" then return false end
            return false
        end
        env.setscriptable = function() return true end
        env.getrawmetatable = function(object)
            return _flame_raw_metas[object] or _flame_base_getmetatable(object)
        end
        env.setmetatable = function(object, meta)
            _flame_raw_metas[object] = meta
            return _flame_base_setmetatable(object, meta)
        end
        env.hookmetamethod = function(object, method, hook)
            local meta = _flame_raw_metas[object] or _flame_base_getmetatable(object)
            if type(meta) ~= "table" then return nil end
            local old = meta[method]
            meta[method] = hook
            _flame_raw_metas[object] = meta
            pcall(_flame_base_setmetatable, object, meta)
            return old
        end
        env.iscclosure = _flame_is_cclosure
        env.islclosure = function(fn) return _flame_base_type(fn) == "function" and not _flame_is_cclosure(fn) end
        _flame_cclosures[env.getgenv] = true
        _flame_cclosures[env.getsenv] = true
        _flame_cclosures[env.getfenv] = true
        _flame_cclosures[env.setfenv] = true
        _flame_cclosures[env.iscclosure] = true
        _flame_cclosures[env.islclosure] = true
        _flame_cclosures[env.getrawmetatable] = true
        _flame_cclosures[env.hookmetamethod] = true
        _flame_cclosures[env.setmetatable] = true
        _flame_cclosures[env.type] = true
        _flame_cclosures[env.gethiddenproperty] = true
        _flame_cclosures[env.isscriptable] = true
        _flame_cclosures[env.setscriptable] = true
        env.debug = _flame_debug_table
        env.getscriptbytecode = function() return "return true" end
        env.rconsoleinput = function() return "input" end
        env.Path2DControlPoint = env.Path2DControlPoint or {
            new = function(position) return {Position = position} end,
        }
    end
    for _, env in ipairs(_flame_envs) do _flame_install_env_api(env) end

    local _flame_instance_api = Instance
    local _flame_old_instance_new
    pcall(function() _flame_old_instance_new = _flame_instance_api.new end)
    if type(_flame_instance_api) == "table" and type(_flame_old_instance_new) == "function" then
        _flame_instance_api.new = function(class_name, ...)
            local object = _flame_old_instance_new(class_name, ...)
            _flame_instance_count = _flame_instance_count + 1
            _flame_instances[#_flame_instances + 1] = object
            local class = tostring(class_name or "")
            if class == "Humanoid" then
                pcall(rawset, object, "GetState", function() return Enum.HumanoidStateType and (Enum.HumanoidStateType.Running or Enum.HumanoidStateType.Landed) end)
            elseif class == "AngularVelocity" or class == "LinearVelocity" then
                pcall(rawset, object, "__flame_constraint_class", class)
