    local _flame_security = {fromCurrent = function() return {} end}
    local function _ken_make_random(seed)
        local state = (tonumber(seed) or math.floor(os.clock() * 1000)) % 2147483647
        if state <= 0 then state = 123456789 end
        local function nextUnit()
            state = (state * 48271) % 2147483647
            return (state - 1) / 2147483646
        end
        local obj = {}
        function obj:NextNumber(minV, maxV)
            local r = nextUnit()
            if minV ~= nil and maxV ~= nil then return minV + (maxV - minV) * r end
            if minV ~= nil then return minV * r end
            return r
        end
        function obj:NextInteger(minV, maxV)
            local a = math.floor(tonumber(minV) or 0)
            local b = math.floor(tonumber(maxV) or a)
            if b < a then a, b = b, a end
            return a + math.floor(nextUnit() * (b - a + 1))
        end
        function obj:NextUnitVector()
            local theta = nextUnit() * math.pi * 2
            local z = nextUnit() * 2 - 1
            local r = math.sqrt(math.max(0, 1 - z * z))
            return Vector3.new(r * math.cos(theta), z, r * math.sin(theta))
        end
        function obj:Shuffle(tbl)
            if type(tbl) ~= "table" then return end
            for i = #tbl, 2, -1 do
                local j = self:NextInteger(1, i)
                tbl[i], tbl[j] = tbl[j], tbl[i]
            end
        end
        function obj:Clone()
            return _ken_make_random(state)
        end
        return _flame_base_setmetatable(obj, {__type = "Random", __metatable = "Random"})
    end
    local _flame_random_old = Random
    local _flame_random = {}
    if type(_flame_random_old) == "table" then for key, value in pairs(_flame_random_old) do _flame_random[key] = value end end
    _flame_random.new = function(seed) return _ken_make_random(seed) end
    rawset(_G, "_kenMakeRandom", _ken_make_random)

    local _flame_region_mt = {__type = "Region3int16"}
    local _flame_region = {new = function(minimum, maximum) return _flame_base_setmetatable({Min = minimum, Max = maximum}, _flame_region_mt) end}
    local _flame_bit32 = bit32 or {}
    _flame_bit32.countrz = function(value)
        local number = tonumber(value) or 0
        if number == 0 then return 32 end
        local count = 0
        while number % 2 == 0 do count = count + 1; number = number / 2 end
        return count
    end
    local _flame_brick_palette = {
        [1]   = {name = "White",                rgb = {242/255, 243/255, 243/255}},
        [21]  = {name = "Bright red",           rgb = {196/255, 40/255, 28/255}},
        [23]  = {name = "Bright blue",          rgb = {13/255, 105/255, 172/255}},
        [24]  = {name = "Bright yellow",        rgb = {245/255, 205/255, 48/255}},
        [26]  = {name = "Black",                rgb = {27/255, 42/255, 53/255}},
        [28]  = {name = "Dark green",           rgb = {40/255, 127/255, 71/255}},
        [37]  = {name = "Bright green",         rgb = {75/255, 151/255, 75/255}},
        [194] = {name = "Medium stone grey",    rgb = {163/255, 162/255, 165/255}},
        [199] = {name = "Dark stone grey",      rgb = {99/255, 95/255, 98/255}},
        [1001] = {name = "Institutional white", rgb = {248/255, 248/255, 248/255}},
        [1003] = {name = "Really black",        rgb = {17/255, 17/255, 17/255}},
        [1004] = {name = "Really red",          rgb = {1, 0, 0}},
        [1009] = {name = "New Yeller",          rgb = {1, 1, 0}},
        [1010] = {name = "Really blue",         rgb = {0, 0, 1}},
        [1020] = {name = "Lime green",          rgb = {0, 1, 0}},
    }
    local _flame_brick_by_name = {}
    for num, info in pairs(_flame_brick_palette) do
        _flame_brick_by_name[info.name:lower()] = {num = num, name = info.name, rgb = info.rgb}
    end
    _flame_brick_by_name["red"] = _flame_brick_by_name["bright red"]
    _flame_brick_by_name["blue"] = _flame_brick_by_name["bright blue"]
    _flame_brick_by_name["green"] = _flame_brick_by_name["bright green"]
    _flame_brick_by_name["yellow"] = _flame_brick_by_name["bright yellow"]

    local _flame_color3 = Color3
    local _flame_brick = {}
    local function _flame_brick_new(value, g, b)
        local entry
        if type(value) == "number" and g ~= nil and b ~= nil then
            return _flame_base_setmetatable({
                Number = 1,
                Name = "Custom",
                Color = _flame_color3.new(value, g, b),
            }, {
                __type = "BrickColor",
                __metatable = "BrickColor",
                __tostring = function(s) return s.Name end,
                __eq = function(x, y) return type(x) == "table" and type(y) == "table" and x.Color == y.Color end,
            })
        elseif type(value) == "number" and _flame_brick_palette[value] then
            local info = _flame_brick_palette[value]
            entry = {num = value, name = info.name, rgb = info.rgb}
        elseif type(value) == "string" then
            entry = _flame_brick_by_name[value:lower()]
        elseif type(value) == "table" and value.R ~= nil then
            return _flame_base_setmetatable({
                Number = 194,
                Name = "Medium stone grey",
                Color = value,
            }, {__type = "BrickColor", __metatable = "BrickColor", __tostring = function(s) return s.Name end})
        end
        entry = entry or {num = 194, name = "Medium stone grey", rgb = {163/255, 162/255, 165/255}}
        return _flame_base_setmetatable({
            Number = entry.num,
            Name = entry.name,
            Color = _flame_color3.new(entry.rgb[1], entry.rgb[2], entry.rgb[3]),
        }, {
            __type = "BrickColor",
            __metatable = "BrickColor",
            __tostring = function(s) return s.Name end,
            __eq = function(x, y) return type(x) == "table" and type(y) == "table" and x.Number == y.Number end,
        })
    end
    _flame_brick.new = _flame_brick_new
    _flame_brick.palette = function(idx) return _flame_brick_new(idx) end
    _flame_brick.random = function() return _flame_brick_new(21) end
    _flame_brick.White = function() return _flame_brick_new("White") end
    _flame_brick.Black = function() return _flame_brick_new("Black") end
    _flame_brick.Red = function() return _flame_brick_new("Red") end
    _flame_brick.Blue = function() return _flame_brick_new("Blue") end
    _flame_brick.Green = function() return _flame_brick_new("Green") end
    _flame_brick.Yellow = function() return _flame_brick_new("Yellow") end
    _flame_brick.DarkGray = function() return _flame_brick_new("Dark stone grey") end
    _flame_brick.Gray = function() return _flame_brick_new("Medium stone grey") end
    _flame_brick.ReallyRed = function() return _flame_brick_new("Really red") end
    rawset(_G, "BrickColor", _flame_brick)

    for _, env in ipairs(_flame_envs) do
        env.SecurityCapabilities = _flame_security
        env.Random = _flame_random
        env.Region3int16 = _flame_region
        env.bit32 = _flame_bit32
        env.BrickColor = _flame_brick
        env.getinstances = _G.getinstances
        env.getnilinstances = _G.getnilinstances
        env.lz4compress = env.lz4compress or function(value) return value end
        env.lz4decompress = env.lz4decompress or function(value) return value end
        env.getscriptbytecode = function() return "return true" end
        env.rconsoleinput = function() return "input" end
        env.Path2DControlPoint = {new = function(position) return {Position = position} end}
        env.type = _flame_function_type
        env.getfenv = _flame_getfenv
        env.setfenv = _flame_setfenv
        env.getgenv = function() return _flame_genv end
        env.islclosure = function(fn) return _flame_base_type(fn) == "function" and not _flame_is_cclosure(fn) end
        env.iscclosure = _flame_is_cclosure
        env.debug = _flame_debug_table
    end

    if Enum then
        pcall(function()
            if Enum.HumanoidStateType.Climbing == nil then rawset(Enum.HumanoidStateType, "Climbing", _flame_base_setmetatable({Name = "Climbing", Value = 0}, {__type = "EnumItem"})) end
            if Enum.HumanoidStateType.Running == nil then rawset(Enum.HumanoidStateType, "Running", _flame_base_setmetatable({Name = "Running", Value = 1}, {__type = "EnumItem"})) end
        end)
    end

    local _flame_old_tick = tick
    local _flame_virtual_time = 0
    for _, env in ipairs(_flame_envs) do
        env.tick = function() return (_flame_old_tick and _flame_old_tick() or os.clock()) + _flame_virtual_time end
    end
    if type(task) == "table" and type(task.wait) == "function" then
        local _flame_old_wait = task.wait
        task.wait = function(duration)
            local dt = tonumber(duration) or (1/60)
            _flame_virtual_time = _flame_virtual_time + math.max(dt, 0)
            local result = _flame_old_wait(duration)
            for _, object in ipairs(_flame_instances) do
                local ok_class, class = pcall(function() return object.ClassName end)
                local ok_parent, parent = pcall(function() return object.Parent end)
                if ok_parent and parent ~= nil and ok_class and (class == "LinearVelocity" or class == "AngularVelocity") then
                    local target = object.Parent
                    if class == "LinearVelocity" then pcall(rawset, target, "AssemblyLinearVelocity", object.VectorVelocity or Vector3.new(0, 50, 0)) end
                    if class == "AngularVelocity" then pcall(rawset, target, "AssemblyAngularVelocity", object.AngularVelocity or Vector3.new(0, 10, 0)) end
                end
            end
            return result
        end
    end

    local _flame_old_hook = hookfunction
    local _flame_old_restore = restorefunction
    local _flame_restore_map = setmetatable({}, {__mode = "k"})
    for _, env in ipairs(_flame_envs) do
        env.hookfunction = function(target, replacement)
            local previous = _flame_old_hook(target, replacement)
            _flame_restore_map[target] = previous
            local registry = rawget(_G, "_hkR")
            if type(registry) == "table" and type(registry[target]) == "table" then registry[target].orig = previous end
            return previous
        end
        env.restorefunction = function(target)
            local registry = rawget(_G, "_hkR")
            local entry = type(registry) == "table" and registry[target]
            if type(entry) == "table" and entry.orig ~= nil then entry.f = entry.orig end
            local previous = _flame_restore_map[target]
            if previous ~= nil and type(registry) == "table" and type(registry[target]) == "table" then registry[target].f = previous end
            return _flame_old_restore(target)
        end
    end
end

-- Payload chunk environment bindings
do
    local _env_ok, _env_name, _env = false, nil, nil
    if _native_debug and type(_native_debug.getupvalue) == "function" then
        _env_ok, _env_name, _env = pcall(_native_debug.getupvalue, chunk, 1)
    end
    if _env_ok and _env_name == "_ENV" and type(_env) == "table" then
        local _base_type = type
        local _base_setmetatable = setmetatable
        local _base_getmetatable = getmetatable
        local _raw_meta = setmetatable({}, {__mode = "k"})
        local _genv = {}
        for key, value in pairs(_env) do _genv[key] = value end
        local function _enum_item(name, value)
            return _base_setmetatable({Name = name, Value = value or 0}, {__type = "EnumItem"})
        end
        local function _instance_type(value)
            local ok_value, kind = pcall(typeof, value)
            if ok_value and kind == "Instance" then return "userdata" end
            return _base_type(value)
        end
        _env.type = _instance_type
        _env.getfenv = function() return _env end
        _env.getgenv = function() return _genv end
        _env.getsenv = function(scriptObj)
            local isInst = (scriptObj == _env.script) or (_base_type(scriptObj) == "table" and (_base_getmetatable(scriptObj) == "Instance" or rawget(scriptObj, "ClassName") ~= nil))
            if not isInst then
                error("invalid argument #1 to 'getsenv' (Instance expected, got " .. _instance_type(scriptObj) .. ")", 2)
            end
