-- Expanded Roblox datatypes, services, and modern executor helpers (modular helpers to stay < 200 locals)
(function()
    local _envs = {}
    local _seen = setmetatable({}, {__mode = "k"})
    local function addEnv(e)
        if type(e) == "table" and not _seen[e] then
            _seen[e] = true
            _envs[#_envs + 1] = e
        end
    end
    addEnv(_G)
    local _ds = rawget(_G, "dumperState")
    if type(_ds) == "table" then
        addEnv(_ds.env)
        addEnv(_ds.dsEnv)
    end
    if _native_debug and type(_native_debug.getupvalue) == "function" then
        pcall(function()
            local ok_c, cname, cenv = _native_debug.getupvalue(chunk, 1)
            if ok_c and cname == "_ENV" then addEnv(cenv) end
        end)
    end

    local function installMissingDataTypes()
        local _st_store = {}
        local SharedTableApi = {
            new = function(init)
                local t = {}
                if type(init) == "table" then for k, v in pairs(init) do t[k] = v end end
                return setmetatable(t, {__type = "SharedTable"})
            end,
            clone = function(st, deep)
                local out = {}
                if type(st) == "table" then for k, v in pairs(st) do out[k] = v end end
                return setmetatable(out, {__type = "SharedTable"})
            end,
            cloneAndFreeze = function(st) return setmetatable(st or {}, {__type = "SharedTable"}) end,
            clear = function(st) if type(st) == "table" then for k in pairs(st) do st[k] = nil end end end,
            size = function(st)
                local n = 0
                if type(st) == "table" then for _ in pairs(st) do n = n + 1 end end
                return n
            end,
            increment = function(st, k, d)
                if type(st) == "table" then st[k] = (tonumber(st[k]) or 0) + (tonumber(d) or 1); return st[k] end
                return 0
            end,
            update = function(st, k, fn)
                if type(st) == "table" and type(fn) == "function" then st[k] = fn(st[k]) end
            end,
        }
        local DateTimeApi = {
            now = function()
                local unix = os.time()
                return {
                    UnixTimestamp = unix,
                    UnixTimestampMillis = unix * 1000,
                    ToIsoDate = function() return os.date("!%Y-%m-%dT%H:%M:%SZ", unix) end,
                    ToLocalTime = function() return os.date("*t", unix) end,
                    ToUniversalTime = function() return os.date("!*t", unix) end,
                    FormatLocalTime = function() return os.date("%Y-%m-%d %H:%M:%S", unix) end,
                    FormatUniversalTime = function() return os.date("!%Y-%m-%d %H:%M:%S", unix) end,
                }
            end,
            fromUnixTimestamp = function(ts)
                local u = tonumber(ts) or 0
                return {UnixTimestamp = u, UnixTimestampMillis = u * 1000, ToIsoDate = function() return os.date("!%Y-%m-%dT%H:%M:%SZ", u) end}
            end,
            fromUnixTimestampMillis = function(ms)
                local u = math.floor((tonumber(ms) or 0) / 1000)
                return {UnixTimestamp = u, UnixTimestampMillis = tonumber(ms) or 0}
            end,
            fromIsoDate = function() return {UnixTimestamp = os.time(), UnixTimestampMillis = os.time() * 1000} end,
        }
        local FontApi = {
            new = function(family, weight, style)
                return setmetatable({Family = tostring(family or ""), Weight = weight, Style = style, Bold = false}, {__type = "Font"})
            end,
            fromEnum = function(enumItem)
                return setmetatable({Family = "rbxasset://fonts/families/SourceSansPro.json", Bold = false}, {__type = "Font"})
            end,
            fromName = function(name)
                return setmetatable({Family = "rbxasset://fonts/families/" .. tostring(name or "SourceSansPro") .. ".json", Bold = false}, {__type = "Font"})
            end,
            fromId = function(id)
                return setmetatable({Family = "rbxassetid://" .. tostring(id or 0), Bold = false}, {__type = "Font"})
            end,
        }
        local ContentApi = {
            none = setmetatable({SourceType = "None", Uri = nil}, {__type = "Content"}),
            fromUri = function(uri) return setmetatable({SourceType = "Uri", Uri = tostring(uri or "")}, {__type = "Content"}) end,
            fromObject = function(obj) return setmetatable({SourceType = "Object", Object = obj}, {__type = "Content"}) end,
        }
        local SecretApi = {
            new = function() return setmetatable({}, {__type = "Secret"}) end,
        }
        local CatalogParamsApi = {
            new = function() return setmetatable({SearchKeyword = "", MinPrice = 0, MaxPrice = 0, SortType = nil}, {__type = "CatalogSearchParams"}) end,
        }
        local DockWidgetApi = {
            new = function(dockState, initEnabled, overrideRestore, floatX, floatY, minX, minY)
                return setmetatable({
                    InitialDockState = dockState,
                    InitialEnabled = initEnabled == true,
                    InitialEnabledShouldOverrideRestore = overrideRestore == true,
                    FloatingXSize = floatX or 200,
                    FloatingYSize = floatY or 200,
                    MinWidth = minX or 100,
                    MinHeight = minY or 100,
                }, {__type = "DockWidgetPluginGuiInfo"})
            end,
        }
        for _, env in ipairs(_envs) do
            if type(env.SharedTable) ~= "table" then env.SharedTable = SharedTableApi end
            if type(env.DateTime) ~= "table" then env.DateTime = DateTimeApi end
            if type(env.Font) ~= "table" then env.Font = FontApi end
            if type(env.Content) ~= "table" then env.Content = ContentApi end
            if type(env.Secret) ~= "table" then env.Secret = SecretApi end
            if type(env.CatalogSearchParams) ~= "table" then env.CatalogSearchParams = CatalogParamsApi end
            if type(env.DockWidgetPluginGuiInfo) ~= "table" then env.DockWidgetPluginGuiInfo = DockWidgetApi end
            if type(env.Instance) == "table" and rawget(env.Instance, "fromExisting") == nil then
                env.Instance.fromExisting = function(existing)
                    if existing == nil then error("Instance.fromExisting requires an Instance", 2) end
                    local cloneFn
                    pcall(function() cloneFn = existing.Clone end)
                    if type(cloneFn) == "function" then return cloneFn(existing) end
                    return existing
                end
            end
        end
    end

    local function installModernServicesAndExecutorHelpers()
        local g = rawget(_G, "game")
        if g ~= nil then
            local extraServices = {
                "TextChatService", "MemoryStoreService", "MessagingService", "PolicyService",
                "LocalizationService", "ProximityPromptService", "GroupService", "InsertService",
                "BadgeService", "SocialService", "HapticService", "VRService", "AnalyticsService",
                "CaptureService", "TestService", "VirtualInputManager", "VirtualUser",
                "ServerScriptService", "ServerStorage", "ReplicatedFirst", "StarterPack",
                "StarterPlayer", "Teams", "LogService", "AssetService", "ContentProvider",
                "Debris", "PathfindingService", "TeleportService", "TextService", "GuiService",
                "ContextActionService", "MarketplaceService", "DataStoreService",
            }
            for _, svcName in ipairs(extraServices) do
                pcall(function() return g:GetService(svcName) end)
            end
        end
        local _noop = function() end
        local _retEmpty = function() return {} end
        local helpers = {
            replicatesignal = _noop,
            compareinstances = function(a, b) return rawequal(a, b) end,
            isourclosure = function(fn) return type(fn) == "function" end,
            getactors = _retEmpty,
            run_on_actor = function(_, fn, ...) if type(fn) == "function" then return pcall(fn, ...) end end,
            create_comm_channel = function() return 1, Instance.new("BindableEvent") end,
            get_comm_channel = function() return Instance.new("BindableEvent") end,
            getsimulationradius = function() return 1000 end,
            setsimulationradius = _noop,
            isrbxactive = function() return true end,
            iswindowactive = function() return true end,
            rconsoleinfo = _noop,
            rconsolewarn = _noop,
            rconsoleerr = _noop,
            rconsoleprint = _noop,
            rconsoletitle = _noop,
            rconsoleclear = _noop,
            rconsoledestroy = _noop,
            rconsolecreate = _noop,
        }
        for _, env in ipairs(_envs) do
            for k, v in pairs(helpers) do
                if env[k] == nil then env[k] = v end
            end
        end
    end

    installMissingDataTypes()
    installModernServicesAndExecutorHelpers()
end)()

-- Pre-execution anti-tamper and type compatibility shims
do
    local function _dumpstring_stub(...)
        error("dumpstring is not supported in this environment", 0)
    end

    rawset(_G, "dumpstring", _dumpstring_stub)

    local _bp = type(_G._BYPASS) == "table" and _G._BYPASS
    local _benv = _bp and type(_bp.env) == "table" and _bp.env
    if _benv then
        rawset(_benv, "dumpstring", _dumpstring_stub)
    end

    local _prev_reset_ds = _G._bypassOnReset
    _G._bypassOnReset = function()
        if _prev_reset_ds then _prev_reset_ds() end
        rawset(_G, "dumpstring", _dumpstring_stub)
        local bp2  = type(_G._BYPASS) == "table" and _G._BYPASS
        local benv2 = bp2 and type(bp2.env) == "table" and bp2.env
        if benv2 then rawset(benv2, "dumpstring", _dumpstring_stub) end
    end
end

do
    if type(_G.Instance) == "table" and type(_G.Instance.new) == "function" then
        local _orig_new = _G.Instance.new
        _G.Instance.new = function(cls, parent)
            local inst = _orig_new(cls, parent)
            if inst and not parent then _grs_new_insts[inst] = true end
            if inst then
                local function ancestor(self2, target, mode)
                    local node = self2.Parent
                    local depth = 0
                    while node ~= nil and depth < 128 do
                        depth = depth + 1
                        local name = node.Name
                        local className = node.ClassName
                        if (mode == "name" and name == target)
                           or (mode == "class" and className == target)
                           or (mode == "isa" and type(node.IsA) == "function" and node:IsA(target)) then
                            return node
                        end
                        node = node.Parent
                    end
                    return nil
                end
                rawset(inst, "FindFirstAncestor", function(self2, name) return ancestor(self2, name, "name") end)
                rawset(inst, "FindFirstAncestorOfClass", function(self2, name) return ancestor(self2, name, "class") end)
                rawset(inst, "FindFirstAncestorWhichIsA", function(self2, name) return ancestor(self2, name, "isa") end)
            end
            return inst
        end
    end

    local function _patch_ffc_on_mt(proxy)
        if type(proxy) ~= "table" then return false end
        local mt = getmetatable(proxy)
        if type(mt) ~= "table" then return false end
        if rawget(mt, "_grs_ffc_done") then return true end
        rawset(mt, "_grs_ffc_done", true)
        local _orig_ffc = rawget(mt, "FindFirstChild") or function() return nil end
        rawset(mt, "FindFirstChild", function(self, name, recursive)
            if name == "Animate" then return _grs_anim end
            return _orig_ffc(self, name, recursive)
        end)
        return true
    end

    pcall(_patch_ffc_on_mt, _G.game)
    local _benv = type(_G._BYPASS) == "table" and type(_G._BYPASS.env) == "table" and _G._BYPASS.env
    if _benv then pcall(_patch_ffc_on_mt, _benv.game) end

    local function _grs_stub() return {_grs_anim} end
    rawset(_G, "getrunningscripts", _grs_stub)
    if _benv then rawset(_benv, "getrunningscripts", _grs_stub) end

    local _prev_grs = _G._bypassOnReset
    _G._bypassOnReset = function()
        if _prev_grs then _prev_grs() end
        pcall(_patch_ffc_on_mt, _G.game)
        local bp2   = type(_G._BYPASS) == "table" and _G._BYPASS
        local benv2 = bp2 and type(bp2.env) == "table" and bp2.env
        if benv2 then
            pcall(_patch_ffc_on_mt, benv2.game)
            rawset(benv2, "getrunningscripts", _grs_stub)
        end
        rawset(_G, "getrunningscripts", _grs_stub)
    end
end

do
    local _ZOOM_DEFAULTS = {
        CameraMinZoomDistance = 0.5,
        CameraMaxZoomDistance = 400,
    }

    local _rawtype = rawtype or (debug and debug.rawtype) or type
    local function _is_tbl(v)
        local t = _rawtype(v)
        return t == "table" or t == "userdata"
    end

    local _pl_svc = _is_tbl(_fake_services) and _fake_services.Players
    local _lp     = _is_tbl(_pl_svc) and rawget(_pl_svc, "LocalPlayer")

    if _is_tbl(_lp) then
        for k in pairs(_ZOOM_DEFAULTS) do rawset(_lp, k, nil) end

        if type(debug) == "table" and type(debug.setmetatable) == "function" then
            local _zoom_mt = {
                __metatable = "Instance",
                __index = function(_, k)
                    local d = _ZOOM_DEFAULTS[k]
                    if d ~= nil then return d end
                    return rawget(_lp, k)
                end,
                __newindex = function(_, k, v)
                    if _ZOOM_DEFAULTS[k] ~= nil then return end
                    rawset(_lp, k, v)
                end,
            }
            if not pcall(debug.setmetatable, _lp, _zoom_mt) then
                for k, v in pairs(_ZOOM_DEFAULTS) do rawset(_lp, k, v) end
            end
        else
            for k, v in pairs(_ZOOM_DEFAULTS) do rawset(_lp, k, v) end
            local _fmt = getmetatable(_lp)
            if type(_fmt) == "table" and not rawget(_fmt, "_zoom_ni_done") then
                rawset(_fmt, "_zoom_ni_done", true)
                local _old_ni = rawget(_fmt, "__newindex")
                rawset(_fmt, "__newindex", function(t, k, v)
                    if _ZOOM_DEFAULTS[k] ~= nil then return end
                    if type(_old_ni) == "function" then
                        return _old_ni(t, k, v)
                    end
                    rawset(t, k, v)
                end)
            end
        end
    end
end

do
    local _orig_dump = _G._origStringDump
                    or (type(string) == "table" and rawget(string, "dump"))
                    or string.dump
    if not _G._origStringDump then _G._origStringDump = _orig_dump end

    local _orig_guv = _G._origGetupvalue
                   or (debug and type(debug) == "table" and rawget(debug, "getupvalue"))
    if not _G._origGetupvalue and _orig_guv then
        _G._origGetupvalue = _orig_guv
    end

    string.dump = function(fn, ...)
        error("attempt to dump given function", 2)
    end

    do
        local _real_gup = debug and type(debug) == "table" and rawget(debug, "getupvalue")
        local _is_cc    = rawget(_G, "iscclosure")
        if rawget(_G, "getupvalue") ~= nil then
            getupvalue = function(fn, i)
                if type(fn) ~= "function" then return nil end
                if _is_cc and _is_cc(fn) then return nil end
                if _real_gup then
                    local ok, n, v = pcall(_real_gup, fn, tonumber(i) or 1)
                    if ok and n ~= nil then return n, v end
                end
                return nil
            end
        end
        if rawget(_G, "getupvalues") ~= nil then
            getupvalues = function(fn)
                if type(fn) ~= "function" then return {} end
                if _is_cc and _is_cc(fn) then return {} end
                local ups = {}
                if _real_gup then
                    for idx = 1, 256 do
                        local ok, name, val = pcall(_real_gup, fn, idx)
                        if not ok or name == nil then break end
                        ups[idx] = val
                    end
                end
                return ups
            end
        end
    end
end

do
    local _known_roblox_mt = {
        Vector3=true, Vector2=true, CFrame=true, Color3=true,
        UDim2=true, UDim=true, BrickColor=true, TweenInfo=true,
        NumberSequence=true, ColorSequence=true, NumberRange=true,
        Rect=true, Ray=true, Axes=true, Faces=true, Region3=true,
        Region3int16=true, Vector3int16=true, Vector2int16=true,
        PhysicalProperties=true, RaycastResult=true, Random=true,
        PathWaypoint=true, Font=true, FloatCurveKey=true,
        RotationCurveKey=true, OverlapParams=true, RaycastParams=true,
        Instance=true, DateTime=true, NumberSequenceKeypoint=true,
        ColorSequenceKeypoint=true, SharedTable=true, Content=true, Secret=true,
    }
    local _prev_typeof = typeof
    typeof = function(v)
        if v == nil then return "nil" end
        local t = type(v)
        if t ~= "table" and t ~= "userdata" then return t end
        if _G._RTYPE and _G._RTYPE[v] then return _G._RTYPE[v] end
        local ok_mt, mt = pcall(getmetatable, v)
        if ok_mt and mt ~= nil then
            if type(mt) == "string" and _known_roblox_mt[mt] then
                return mt
            end
            if type(mt) == "table" then
                if type(mt.__type) == "string" then return mt.__type end
                if type(mt.__metatable) == "string"
                   and _known_roblox_mt[mt.__metatable] then
                    return mt.__metatable
                end
            end
        end
        if type(_prev_typeof) == "function" then
            return _prev_typeof(v)
        end
        return t
    end

    if type(_G.Vector3) ~= "table" or _G.Vector3.FromAxis == nil then
        local old_api = _G.Vector3
        local api = {}
        if type(old_api) == "table" then
            for key, value in pairs(old_api) do api[key] = value end
        end
        local vector_mt = {
            __type = "Vector3",
            __metatable = "Vector3",
            __index = function(obj, key)
                local x = rawget(obj, "X") or 0
                local y = rawget(obj, "Y") or 0
                local z = rawget(obj, "Z") or 0
                if key == "Magnitude" then return math.sqrt(x*x + y*y + z*z) end
                if key == "Unit" then
                    local magnitude = math.sqrt(x*x + y*y + z*z)
                    if magnitude == 0 then magnitude = 1 end
                    return api.new(x/magnitude, y/magnitude, z/magnitude)
                end
                if key == "Dot" then return function(_, other)
                    return x*(other.X or 0) + y*(other.Y or 0) + z*(other.Z or 0)
                end end
                if key == "Cross" then return function(_, other)
                    return api.new(y*(other.Z or 0)-z*(other.Y or 0), z*(other.X or 0)-x*(other.Z or 0), x*(other.Y or 0)-y*(other.X or 0))
                end end
                if key == "Lerp" then return function(_, goal, alpha)
                    local a = tonumber(alpha) or 0
                    return api.new(x + ((goal.X or 0) - x) * a, y + ((goal.Y or 0) - y) * a, z + ((goal.Z or 0) - z) * a)
                end end
                if key == "Abs" then return function() return api.new(math.abs(x), math.abs(y), math.abs(z)) end end
                if key == "Ceil" then return function() return api.new(math.ceil(x), math.ceil(y), math.ceil(z)) end end
                if key == "Floor" then return function() return api.new(math.floor(x), math.floor(y), math.floor(z)) end end
                if key == "Sign" then return function() return api.new(math.sign(x), math.sign(y), math.sign(z)) end end
                if key == "Min" then return function(_, other) return api.new(math.min(x, other.X or 0), math.min(y, other.Y or 0), math.min(z, other.Z or 0)) end end
                if key == "Max" then return function(_, other) return api.new(math.max(x, other.X or 0), math.max(y, other.Y or 0), math.max(z, other.Z or 0)) end end
                if key == "FuzzyEq" then return function(_, other, eps)
                    local e = tonumber(eps) or 1e-5
                    return math.abs(x - (other.X or 0)) <= e and math.abs(y - (other.Y or 0)) <= e and math.abs(z - (other.Z or 0)) <= e
                end end
                if key == "Angle" then return function(_, other)
                    local m1 = math.sqrt(x*x + y*y + z*z)
                    local ox, oy, oz = other.X or 0, other.Y or 0, other.Z or 0
                    local m2 = math.sqrt(ox*ox + oy*oy + oz*oz)
                    if m1 == 0 or m2 == 0 then return 0 end
                    local cosA = math.max(-1, math.min(1, (x*ox + y*oy + z*oz) / (m1 * m2)))
                    return math.acos(cosA)
                end end
                return nil
            end,
            __tostring = function(obj)
                return string.format("%g, %g, %g", rawget(obj, "X") or 0, rawget(obj, "Y") or 0, rawget(obj, "Z") or 0)
            end,
            __add = function(a, b) return api.new((a.X or 0)+(b.X or 0), (a.Y or 0)+(b.Y or 0), (a.Z or 0)+(b.Z or 0)) end,
            __sub = function(a, b) return api.new((a.X or 0)-(b.X or 0), (a.Y or 0)-(b.Y or 0), (a.Z or 0)-(b.Z or 0)) end,
            __unm = function(a) return api.new(-(a.X or 0), -(a.Y or 0), -(a.Z or 0)) end,
            __mul = function(a, b)
                if type(a) == "number" then return api.new(a*(b.X or 0), a*(b.Y or 0), a*(b.Z or 0)) end
                if type(b) == "table" then return api.new((a.X or 0)*(b.X or 0), (a.Y or 0)*(b.Y or 0), (a.Z or 0)*(b.Z or 0)) end
                return api.new((a.X or 0)*(b or 0), (a.Y or 0)*(b or 0), (a.Z or 0)*(b or 0))
            end,
            __div = function(a, b)
                if type(b) == "table" then return api.new((a.X or 0)/(b.X or 1), (a.Y or 0)/(b.Y or 1), (a.Z or 0)/(b.Z or 1)) end
                return api.new((a.X or 0)/(b or 1), (a.Y or 0)/(b or 1), (a.Z or 0)/(b or 1))
            end,
            __eq = function(a, b) return a.X == b.X and a.Y == b.Y and a.Z == b.Z end,
        }
        api.new = function(x, y, z)
            return setmetatable({X=tonumber(x) or 0, Y=tonumber(y) or 0, Z=tonumber(z) or 0}, vector_mt)
        end
        api.zero = api.new(0, 0, 0)
        api.one = api.new(1, 1, 1)
        api.xAxis = api.new(1, 0, 0)
        api.yAxis = api.new(0, 1, 0)
        api.zAxis = api.new(0, 0, 1)
        rawset(_G, "Vector3", api)
    end

    if type(_G.utf8) ~= "table" then _G.utf8 = {} end
    if type(_G.utf8.len) ~= "function" then
        _G.utf8.len = function(s, i, j)
            if type(s) ~= "string" then
                error("bad argument #1 to 'utf8.len' (string expected, got " .. type(s) .. ")", 2)
            end
            i = i or 1
            j = j or #s
            local count = 0
            local pos   = i
            while pos <= j do
                local b = string.byte(s, pos)
                if     b < 0x80 then pos = pos + 1
                elseif b < 0xC0 then return nil, pos
                elseif b < 0xE0 then pos = pos + 2
                elseif b < 0xF0 then pos = pos + 3
                else                  pos = pos + 4
                end
                count = count + 1
            end
            return count
        end
    end
    if type(_G.utf8.char) ~= "function" then _G.utf8.char = string.char end
    if type(_G.utf8.codepoint) ~= "function" then _G.utf8.codepoint = string.byte end
    if type(_G.utf8.nfdnormalize) ~= "function" then _G.utf8.nfdnormalize = function(value) return value end end
    if type(_G.utf8.nfcnormalize) ~= "function" then _G.utf8.nfcnormalize = function(value) return value end end
    if type(_G.utf8.graphemes) ~= "function" then
        _G.utf8.graphemes = function(value)
            local index = 0
            local text = tostring(value or "")
            return function()
                index = index + 1
                if index <= #text then return index, index end
            end
        end
    end
    if type(_G.math.isnan) ~= "function" then _G.math.isnan = function(value) return value ~= value end end
    if type(_G.math.isfinite) ~= "function" then _G.math.isfinite = function(value) return value == value and value ~= math.huge and value ~= -math.huge end end
    if type(_G.math.isinf) ~= "function" then _G.math.isinf = function(value) return value == math.huge or value == -math.huge end end
    if type(_G.debug.setmemorycategory) ~= "function" then _G.debug.setmemorycategory = function() end end
    if type(_G.debug.profilebegin) ~= "function" then _G.debug.profilebegin = function() end end
    if type(_G.debug.getmemorycategory) ~= "function" then _G.debug.getmemorycategory = function() return "" end end
    if type(_G.debug.resetmemorycategory) ~= "function" then _G.debug.resetmemorycategory = function() end end
    if type(_G.debug.profileend) ~= "function" then _G.debug.profileend = function() end end
    if type(_G.task.desynchronize) ~= "function" then _G.task.desynchronize = function() end end
    if type(_G.task.synchronize) ~= "function" then _G.task.synchronize = function() end end

    local function _patch_env(env)
        if type(env) ~= "table" then return end
        env.typeof  = typeof
        env._VERSION = "Luau"
        env.Vector3 = _G.Vector3
        env.utf8    = _G.utf8
        env.print   = _G.print
        local _base_err = rawget(env, "error") or error
        env.error = function(msg, lvl)
            if msg == "" or msg == nil then return end
            return _base_err(msg, (lvl or 1) + 1)
        end
    end

    local _ds = _G.dumperState
    if type(_ds) == "table" then
        _patch_env(_ds.env)
        _patch_env(_ds.dsEnv)
    end
    local _prev_onreset = _G._bypassOnReset
    _G._bypassOnReset = function()
        if type(_prev_onreset) == "function" then pcall(_prev_onreset) end
        local ds2 = _G.dumperState
        if type(ds2) == "table" then
            _patch_env(ds2.env)
            _patch_env(ds2.dsEnv)
        end
    end
end

local ok, runErr = pcall(chunk)
if not ok then log("runtime: " .. tostring(runErr)) end

do
    local needs_flush = true
    local fprobe = io.open(OUTPUT, "rb")
    if fprobe then
        local body = fprobe:read("*a") or ""
        fprobe:close()
        if #body > 0 then needs_flush = false end
    end
    if needs_flush and type(_G.__plain_tee_buffer) == "table"
       and #_G.__plain_tee_buffer > 0 then
        local of = io.open(OUTPUT, "wb")
        if of then
            of:write(table.concat(_G.__plain_tee_buffer))
            of:close()
            log(("plain-chunk output flushed to %s (%d entries)")
                :format(OUTPUT, #_G.__plain_tee_buffer))
        end
    end
end

local function sanitize_output(path)
    local f = io.open(path, "rb"); if not f then return end
    local body = f:read("*a"); f:close()
    if not body or #body == 0 then return end
    local fixes = 0
    local cleaned = (body:gsub("([^\n]+)", function(line)
        if line:find("^%s*%-%- %[sanitized%]") then return line end
        if line:find("%.%.InvokeServer%(") then
            fixes = fixes + 1
            return "-- [sanitized] broken InvokeServer chain: "
                .. line:gsub("^%s+", "")
        end
        if line:find("[%w_]+%.%s*,") and line:find("%(") then
            fixes = fixes + 1
            return "-- [sanitized] empty-key proxy index: "
                .. line:gsub("^%s+", "")
        end
        return line
    end))
    if fixes > 0 then
        local of = io.open(path, "wb")
        if of then of:write(cleaned); of:close() end
        log(("sanitized %d broken line(s) in %s"):format(fixes, path))
    end
end
pcall(sanitize_output, OUTPUT)

local probe = io.open(OUTPUT, "rb")
if probe then probe:close(); os.exit(0) end

io.stderr:write("[env] no output captured\n")
os.exit(1)
